import type { RawQ } from "../types";
// Fiqh of fasting (ṣawm, iʿtikāf, Zakāt al-Fiṭr), zakāt and ḥajj/ʿumra, with the differences of the four Sunni schools. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  // ───────────── Ṣawm ─────────────
  { id: "fqz-001", s: "fiqh", g: 1, d: 1, t: ["sawm-basics", "ramadan"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṣiyām", v: "2:185", tr: ["ijma"],
    en: ["In which month is fasting obligatory for every adult, sane Muslim who is able, as the verse shown states?", ["Ramaḍān", "Shaʿbān", "Shawwāl", "Muḥarram"], "The verse shown names the month of Ramaḍān, in which the Quran was sent down, as the month of obligatory fasting. Fasting in Shaʿbān and Muḥarram is recommended, not obligatory."],
    de: ["In welchem Monat ist das Fasten für jeden erwachsenen, verständigen und fähigen Muslim verpflichtend, wie die angezeigte Āya festlegt?", ["Ramaḍān", "Šaʿbān", "Šauwāl", "Muḥarram"], "Die angezeigte Āya nennt den Monat Ramaḍān, in dem der Koran herabgesandt wurde, als Monat des Pflichtfastens. Das Fasten im Šaʿbān und Muḥarram ist empfohlen, nicht verpflichtend."],
    ar: ["في أيّ شهر يجب الصوم على كل مسلم بالغ عاقل قادر كما تنص الآية المعروضة؟", ["رمضان", "شعبان", "شوال", "المحرّم"], "نصّت الآية المعروضة على شهر رمضان الذي أُنزل فيه القرآن شهرًا للصوم الواجب، أما صوم شعبان والمحرّم فمستحب لا واجب."] },

  { id: "fqz-002", s: "fiqh", g: 1, d: 1, t: ["sawm-basics", "fasting-times"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṣiyām", v: "2:187", tr: ["ijma"],
    en: ["According to the verse shown, from when to when does the daily fast last?", ["From true dawn until nightfall at sunset", "From sunrise until sunset", "From the ʿIshāʾ prayer until the ʿAṣr prayer", "From midnight until midday"], "The verse permits eating and drinking until the white thread of dawn becomes distinct from the black, then commands completing the fast until night, which begins at sunset. The fast therefore starts at true dawn (al-fajr al-ṣādiq), not at sunrise."],
    de: ["Von wann bis wann dauert das tägliche Fasten nach der angezeigten Āya?", ["Von der echten Morgendämmerung bis zum Einbruch der Nacht bei Sonnenuntergang", "Vom Sonnenaufgang bis zum Sonnenuntergang", "Vom ʿIšāʾ-Gebet bis zum ʿAṣr-Gebet", "Von Mitternacht bis Mittag"], "Die Āya erlaubt Essen und Trinken, bis sich der weiße Faden der Dämmerung vom schwarzen abhebt, und gebietet dann, das Fasten bis zur Nacht zu vollenden, die mit dem Sonnenuntergang beginnt. Das Fasten beginnt also mit der echten Morgendämmerung (al-faǧr aṣ-ṣādiq), nicht mit dem Sonnenaufgang."],
    ar: ["من متى إلى متى يمتد الصوم اليومي بحسب الآية المعروضة؟", ["من طلوع الفجر الصادق إلى دخول الليل بغروب الشمس", "من طلوع الشمس إلى غروبها", "من صلاة العشاء إلى صلاة العصر", "من منتصف الليل إلى منتصف النهار"], "أباحت الآية الأكل والشرب حتى يتبين الخيط الأبيض من الخيط الأسود من الفجر، ثم أمرت بإتمام الصيام إلى الليل، وأوله غروب الشمس؛ فالصوم يبدأ بالفجر الصادق لا بطلوع الشمس."] },

  { id: "fqz-003", s: "fiqh", g: 1, d: 1, t: ["sawm-exemptions", "ramadan"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṣiyām, on the traveller and the sick", v: "2:184",
    en: ["Which person does the verse shown allow to leave the fast of Ramaḍān and make up the days later?", ["A traveller on a journey", "A person with a long working day", "A student before an examination", "A person who simply feels hungry"], "The verse names the sick and the traveller: they may break the fast and make up the same number of days afterwards. Ordinary hardship such as work, study or hunger is not an excuse."],
    de: ["Welcher Person erlaubt die angezeigte Āya, das Fasten im Ramaḍān zu unterlassen und die Tage später nachzuholen?", ["Einem Reisenden auf einer Reise", "Einer Person mit einem langen Arbeitstag", "Einem Schüler vor einer Prüfung", "Einer Person, die einfach Hunger verspürt"], "Die Āya nennt den Kranken und den Reisenden: Sie dürfen das Fasten brechen und dieselbe Anzahl von Tagen danach nachholen. Gewöhnliche Mühe wie Arbeit, Lernen oder Hunger ist kein Entschuldigungsgrund."],
    ar: ["مَن الذي تبيح له الآية المعروضة الفطر في رمضان مع القضاء بعده؟", ["المسافر في سفره", "صاحب يوم العمل الطويل", "الطالب قبل الامتحان", "من يشعر بالجوع فحسب"], "ذكرت الآية المريض والمسافر، فلهما الفطر وعليهما عدة من أيام أُخر، أما المشقة المعتادة كالعمل والدراسة والجوع فليست عذرًا."] },

  { id: "fqz-004", s: "fiqh", g: 1, d: 2, t: ["sawm-nullifiers", "forgetfulness"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṣiyām; Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣiyām", tr: ["jumhur", "maliki"],
    en: ["According to the majority (Ḥanafīs, Shāfiʿīs, Ḥanbalīs), what is the ruling on someone who eats out of forgetfulness during an obligatory fast?", ["The fast remains valid and no make-up is due", "The fast is void and must be made up", "The fast is void and an expiation is due", "The fast is valid but a fidya is due"], "The majority rely on the hadith of Abū Hurayra in al-Bukhārī and Muslim that whoever forgets and eats or drinks should complete his fast, for Allah fed him. The Mālikīs hold that in an obligatory fast he must make it up, but without sin or expiation."],
    de: ["Was gilt nach der Mehrheit (Ḥanafiten, Šāfiʿiten, Ḥanbaliten) für jemanden, der während eines Pflichtfastens aus Vergesslichkeit isst?", ["Das Fasten bleibt gültig, kein Nachholen ist nötig", "Das Fasten ist ungültig und muss nachgeholt werden", "Das Fasten ist ungültig und eine Sühne ist fällig", "Das Fasten ist gültig, aber eine Fidya ist fällig"], "Die Mehrheit stützt sich auf den Hadith von Abū Huraira bei al-Buḫārī und Muslim: Wer vergisst und isst oder trinkt, soll sein Fasten vollenden, denn Allah hat ihn gespeist. Die Malikiten sehen beim Pflichtfasten ein Nachholen vor, jedoch ohne Sünde und ohne Sühne."],
    ar: ["ما حكم من أكل ناسيًا في صوم واجب عند الجمهور (الحنفية والشافعية والحنابلة)؟", ["صومه صحيح ولا قضاء عليه", "فسد صومه وعليه القضاء", "فسد صومه وعليه الكفارة", "صومه صحيح وعليه الفدية"], "استدل الجمهور بحديث أبي هريرة في الصحيحين: من نسي فأكل أو شرب فليتمّ صومه فإنما أطعمه الله وسقاه. وذهب المالكية إلى وجوب القضاء في الفرض دون إثم ولا كفارة."] },

  { id: "fqz-005", s: "fiqh", g: 1, d: 2, t: ["sawm-exemptions", "hayd"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ḥayḍ; Ibn Qudāma, al-Mughnī, Kitāb al-Ṣiyām", tr: ["ijma"],
    en: ["A woman menstruates during Ramaḍān. What is the agreed ruling?", ["She does not fast and makes up the missed days, but not the missed prayers", "She fasts and makes up the days afterwards as a precaution", "She does not fast and pays a fidya instead of making up", "She does not fast and makes up both the fasts and the prayers"], "By consensus, fasting is not valid during menstruation. ʿĀʾisha reported in Ṣaḥīḥ Muslim that they were ordered to make up the fasts but not the prayers."],
    de: ["Eine Frau hat im Ramaḍān ihre Menstruation. Was ist das einhellige Urteil?", ["Sie fastet nicht und holt die Fastentage nach, die Gebete jedoch nicht", "Sie fastet und holt die Tage vorsichtshalber später nach", "Sie fastet nicht und zahlt statt Nachholens eine Fidya", "Sie fastet nicht und holt Fastentage und Gebete nach"], "Nach Konsens ist das Fasten während der Menstruation nicht gültig. ʿĀʾiša berichtete in Ṣaḥīḥ Muslim, dass ihnen befohlen wurde, das Fasten nachzuholen, nicht aber das Gebet."],
    ar: ["امرأة حاضت في رمضان، فما الحكم المتفق عليه؟", ["لا تصوم وتقضي الصوم دون الصلاة", "تصوم ثم تقضي الأيام احتياطًا", "لا تصوم وتفدي بدل القضاء", "لا تصوم وتقضي الصوم والصلاة"], "أجمع العلماء على أن الحائض لا يصح صومها، وقالت عائشة كما في صحيح مسلم: كنا نؤمر بقضاء الصوم ولا نؤمر بقضاء الصلاة."] },

  { id: "fqz-006", s: "fiqh", g: 1, d: 2, t: ["recommended-fasts", "arafa"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ṣiyām (hadith of Abū Qatāda)",
    en: ["According to the hadith of Abū Qatāda in Ṣaḥīḥ Muslim, fasting the Day of ʿArafa (for one not on ḥajj) is hoped to expiate what?", ["The sins of the previous year and the coming year", "The sins of the previous year only", "The sins of the past month", "All sins of a lifetime"], "In that hadith the Prophet ﷺ said he hoped that fasting the Day of ʿArafa expiates the year before and the year after, and that fasting ʿĀshūrāʾ expiates the year before."],
    de: ["Was sühnt nach dem Hadith von Abū Qatāda in Ṣaḥīḥ Muslim das Fasten am Tag von ʿArafa (für Nicht-Pilger) der Hoffnung nach?", ["Die Sünden des vergangenen und des kommenden Jahres", "Nur die Sünden des vergangenen Jahres", "Die Sünden des vergangenen Monats", "Alle Sünden eines ganzen Lebens"], "In diesem Hadith sagte der Prophet ﷺ, er hoffe, dass das Fasten am Tag von ʿArafa das Jahr davor und das Jahr danach sühnt und das Fasten an ʿĀšūrāʾ das Jahr davor."],
    ar: ["بحسب حديث أبي قتادة في صحيح مسلم، ماذا يُرجى أن يكفّر صوم يوم عرفة لغير الحاج؟", ["السنة الماضية والسنة الباقية", "السنة الماضية وحدها", "ذنوب الشهر الماضي", "ذنوب العمر كله"], "قال النبي ﷺ في هذا الحديث: صيام يوم عرفة أحتسب على الله أن يكفّر السنة التي قبله والسنة التي بعده، وصيام عاشوراء يكفّر السنة التي قبله."] },

  { id: "fqz-007", s: "fiqh", g: 1, d: 1, t: ["forbidden-fasts", "eid"], src: "al-Bukhārī and Muslim, Kitāb al-Ṣawm (hadith of Abū Saʿīd); Ibn Qudāma, al-Mughnī", tr: ["ijma"],
    en: ["On which days is fasting prohibited by consensus?", ["The two days of ʿĪd", "Every Friday", "The day of ʿĀshūrāʾ", "The first day of Shaʿbān"], "The Prophet ﷺ forbade fasting on the day of ʿĪd al-Fiṭr and the day of ʿĪd al-Aḍḥā, and the scholars agree that fasting them is forbidden. Singling out Friday alone is disliked, not forbidden in the same way."],
    de: ["An welchen Tagen ist das Fasten nach Konsens verboten?", ["An den beiden ʿĪd-Tagen", "An jedem Freitag", "Am Tag von ʿĀšūrāʾ", "Am ersten Tag des Šaʿbān"], "Der Prophet ﷺ verbot das Fasten am Tag des ʿĪd al-Fiṭr und des ʿĪd al-Aḍḥā; die Gelehrten sind sich über das Verbot einig. Den Freitag allein herauszugreifen ist verpönt, aber nicht in gleicher Weise verboten."],
    ar: ["في أيّ الأيام يحرم الصوم بالإجماع؟", ["يوما العيدين", "كل يوم جمعة", "يوم عاشوراء", "أول يوم من شعبان"], "نهى النبي ﷺ عن صوم يوم الفطر ويوم الأضحى، وأجمع العلماء على تحريم صومهما، أما إفراد الجمعة بالصوم فمكروه لا محرّم كتحريمهما."] },

  { id: "fqz-008", s: "fiqh", g: 1, d: 2, t: ["zakat-al-fitr"], src: "al-Bukhārī and Muslim, Kitāb al-Zakāt (hadith of Ibn ʿUmar)",
    en: ["In the hadith of Ibn ʿUmar in al-Bukhārī and Muslim, how much did the Prophet ﷺ prescribe as Zakāt al-Fiṭr from dates or barley per person?", ["One ṣāʿ", "One mudd", "Half a ṣāʿ", "Two ṣāʿs"], "Ibn ʿUmar reported that the Prophet ﷺ prescribed Zakāt al-Fiṭr as one ṣāʿ of dates or one ṣāʿ of barley for every Muslim, young or old. The Ḥanafīs accept half a ṣāʿ when it is paid in wheat."],
    de: ["Wie viel schrieb der Prophet ﷺ nach dem Hadith von Ibn ʿUmar bei al-Buḫārī und Muslim als Zakāt al-Fiṭr aus Datteln oder Gerste pro Person vor?", ["Ein Ṣāʿ", "Ein Mudd", "Ein halbes Ṣāʿ", "Zwei Ṣāʿ"], "Ibn ʿUmar berichtete, dass der Prophet ﷺ die Zakāt al-Fiṭr als ein Ṣāʿ Datteln oder ein Ṣāʿ Gerste für jeden Muslim, jung oder alt, festlegte. Die Ḥanafiten lassen bei Weizen ein halbes Ṣāʿ genügen."],
    ar: ["في حديث ابن عمر في الصحيحين، كم فرض النبي ﷺ زكاةَ الفطر من التمر أو الشعير عن كل شخص؟", ["صاعًا", "مُدًّا", "نصف صاع", "صاعين"], "روى ابن عمر أن النبي ﷺ فرض زكاة الفطر صاعًا من تمر أو صاعًا من شعير على كل مسلم صغير أو كبير، ويجيز الحنفية نصف صاع من البُرّ."] },

  { id: "fqz-009", s: "fiqh", g: 1, d: 2, t: ["zakat-al-fitr", "fasting-times"], src: "al-Bukhārī and Muslim, Kitāb al-Zakāt (hadith of Ibn ʿUmar); Ibn Qudāma, al-Mughnī, Bāb Zakāt al-Fiṭr",
    en: ["By what time did the Prophet ﷺ command Zakāt al-Fiṭr to be handed over?", ["Before the people go out to the ʿĪd prayer", "Before the last ten nights of Ramaḍān", "Within three days after ʿĪd", "Any time before the next Ramaḍān"], "In the hadith of Ibn ʿUmar the Prophet ﷺ ordered that it be paid before the people go out to the prayer. Delaying it past the day of ʿĪd without excuse is sinful according to the scholars, though it remains a debt to be paid."],
    de: ["Bis wann befahl der Prophet ﷺ, die Zakāt al-Fiṭr zu übergeben?", ["Bevor die Leute zum ʿĪd-Gebet hinausgehen", "Vor den letzten zehn Nächten des Ramaḍān", "Innerhalb von drei Tagen nach dem ʿĪd", "Jederzeit vor dem nächsten Ramaḍān"], "Im Hadith von Ibn ʿUmar befahl der Prophet ﷺ, sie zu entrichten, bevor die Leute zum Gebet hinausgehen. Sie ohne Grund über den ʿĪd-Tag hinaus aufzuschieben, ist nach den Gelehrten eine Sünde; sie bleibt aber eine zu begleichende Schuld."],
    ar: ["إلى متى أمر النبي ﷺ بأداء زكاة الفطر؟", ["قبل خروج الناس إلى صلاة العيد", "قبل العشر الأواخر من رمضان", "في ثلاثة أيام بعد العيد", "في أي وقت قبل رمضان القادم"], "في حديث ابن عمر أمر النبي ﷺ بها أن تؤدّى قبل خروج الناس إلى الصلاة، وتأخيرها عن يوم العيد بلا عذر إثمٌ عند العلماء مع بقائها دينًا في الذمة."] },

  { id: "fqz-010", s: "fiqh", g: 2, d: 2, t: ["sawm-sunan", "suhur"], src: "al-Bukhārī and Muslim, Kitāb al-Ṣawm (hadith of Sahl ibn Saʿd)",
    en: ["According to the hadith of Sahl ibn Saʿd in al-Bukhārī and Muslim, people remain in goodness as long as they do what?", ["Hasten to break the fast", "Delay breaking the fast until the stars appear", "Fast continuously without breaking", "Break the fast only after the Maghrib prayer"], "The Prophet ﷺ said that people will remain in goodness as long as they hasten the ifṭār. Hastening the ifṭār once sunset is certain and delaying the suḥūr are among the sunan of fasting."],
    de: ["Was müssen die Leute nach dem Hadith von Sahl ibn Saʿd bei al-Buḫārī und Muslim tun, damit sie im Guten bleiben?", ["Das Fastenbrechen beschleunigen", "Das Fastenbrechen bis zum Erscheinen der Sterne hinauszögern", "Ununterbrochen fasten, ohne zu brechen", "Das Fasten erst nach dem Maġrib-Gebet brechen"], "Der Prophet ﷺ sagte, die Menschen bleiben im Guten, solange sie den Ifṭār beschleunigen. Den Ifṭār nach sicherem Sonnenuntergang zu beschleunigen und den Suḥūr hinauszuzögern gehört zu den Sunan des Fastens."],
    ar: ["بحسب حديث سهل بن سعد في الصحيحين، لا يزال الناس بخير ما فعلوا ماذا؟", ["ما عجّلوا الفطر", "ما أخّروا الفطر إلى ظهور النجوم", "ما واصلوا الصيام", "ما أفطروا بعد صلاة المغرب"], "قال النبي ﷺ: لا يزال الناس بخير ما عجّلوا الفطر. ومن سنن الصيام تعجيل الفطر عند تحقق الغروب وتأخير السحور."] },

  { id: "fqz-011", s: "fiqh", g: 2, d: 2, t: ["sawm-nullifiers", "vomiting"], src: "Abū Dāwūd and al-Tirmidhī, Kitāb al-Ṣawm (hadith of Abū Hurayra); Ibn Qudāma, al-Mughnī", tr: ["jumhur"],
    en: ["According to the majority, what is the difference between vomiting deliberately and being overcome by vomit while fasting?", ["Deliberate vomiting breaks the fast and requires make-up; involuntary vomiting does not", "Both break the fast and require make-up", "Neither breaks the fast", "Involuntary vomiting breaks the fast; deliberate vomiting only reduces the reward"], "The hadith of Abū Hurayra in Abū Dāwūd and al-Tirmidhī states that whoever is overcome by vomit owes no make-up, while whoever makes himself vomit must make up the day. The majority of jurists act on this distinction."],
    de: ["Worin unterscheidet sich nach der Mehrheit absichtliches Erbrechen vom unwillkürlichen Erbrechen während des Fastens?", ["Absichtliches Erbrechen bricht das Fasten und verlangt Nachholen, unwillkürliches nicht", "Beides bricht das Fasten und verlangt Nachholen", "Keines von beiden bricht das Fasten", "Unwillkürliches Erbrechen bricht das Fasten, absichtliches mindert nur den Lohn"], "Der Hadith von Abū Huraira bei Abū Dāwūd und at-Tirmiḏī besagt: Wen das Erbrechen überkommt, der muss nicht nachholen; wer sich absichtlich erbricht, muss den Tag nachholen. Die Mehrheit der Juristen folgt dieser Unterscheidung."],
    ar: ["ما الفرق عند الجمهور بين من استقاء عمدًا ومن ذرعه القيء وهو صائم؟", ["من استقاء عمدًا أفطر وعليه القضاء، ومن ذرعه القيء فلا شيء عليه", "كلاهما يفطر وعليه القضاء", "لا يفطر واحد منهما", "من ذرعه القيء أفطر، ومن استقاء نقص أجره فقط"], "في حديث أبي هريرة عند أبي داود والترمذي: من ذرعه القيء فليس عليه قضاء، ومن استقاء عمدًا فليقض، وعليه عمل جمهور الفقهاء."] },

  { id: "fqz-012", s: "fiqh", g: 2, d: 3, t: ["sawm-intention", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Ṣawm", tr: ["hanafi", "comparative"],
    en: ["According to the Ḥanafī school, until when may the intention for a Ramaḍān fast be made if it was not made at night?", ["Until before the midpoint of the day, counted from dawn", "Only before dawn, never during the day", "Until the ʿAṣr prayer", "Until just before sunset"], "Al-Hidāya permits the intention for Ramaḍān, a vow tied to a specific day and voluntary fasts from the night until before the middle of the sharʿī day. The Shāfiʿīs and Ḥanbalīs require an obligatory fast to be intended during the night."],
    de: ["Bis wann darf nach der ḥanafitischen Schule die Absicht für ein Ramaḍān-Fasten gefasst werden, wenn sie nicht in der Nacht gefasst wurde?", ["Bis vor der Mitte des Tages, gerechnet ab der Morgendämmerung", "Nur vor der Morgendämmerung, nie am Tag", "Bis zum ʿAṣr-Gebet", "Bis kurz vor Sonnenuntergang"], "Al-Hidāya erlaubt die Absicht für den Ramaḍān, für ein an einen bestimmten Tag gebundenes Gelübde und für freiwilliges Fasten von der Nacht an bis vor der Mitte des šarʿī-Tages. Šāfiʿiten und Ḥanbaliten verlangen beim Pflichtfasten die Absicht in der Nacht."],
    ar: ["إلى متى تصح نية صوم رمضان عند الحنفية إذا لم ينوِ من الليل؟", ["إلى ما قبل نصف النهار الشرعي", "قبل الفجر فقط ولا تصح نهارًا", "إلى صلاة العصر", "إلى ما قبل الغروب بقليل"], "أجاز صاحب الهداية نية رمضان والنذر المعيّن والنفل من الليل إلى ما قبل نصف النهار، أما الشافعية والحنابلة فيشترطون تبييت النية في الصوم الواجب."] },

  { id: "fqz-013", s: "fiqh", g: 2, d: 3, t: ["sawm-intention", "school-differences"], src: "Khalīl, al-Mukhtaṣar, Bāb al-Ṣiyām; Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣiyām", tr: ["maliki", "comparative"],
    en: ["Which school holds that a single intention at the start of Ramaḍān suffices for the whole month, as long as the fast is not interrupted?", ["The Mālikī school", "The Shāfiʿī school", "The Ḥanafī school", "The Ḥanbalī school (its relied view)"], "The Mālikīs treat the consecutive fast of Ramaḍān as one act of worship, so one night intention covers it unless it is broken, for example by travel or illness. The Shāfiʿīs and the relied Ḥanbalī view require a fresh intention every night."],
    de: ["Welche Schule hält eine einzige Absicht zu Beginn des Ramaḍān für den ganzen Monat für ausreichend, solange das Fasten nicht unterbrochen wird?", ["Die malikitische Schule", "Die šāfiʿitische Schule", "Die ḥanafitische Schule", "Die ḥanbalitische Schule (maßgebliche Ansicht)"], "Die Malikiten betrachten das zusammenhängende Ramaḍān-Fasten als eine Gottesdiensthandlung, sodass eine nächtliche Absicht genügt, solange es nicht etwa durch Reise oder Krankheit unterbrochen wird. Šāfiʿiten und die maßgebliche ḥanbalitische Ansicht verlangen jede Nacht eine neue Absicht."],
    ar: ["أيّ مذهب يكتفي بنية واحدة في أول رمضان للشهر كله ما لم ينقطع التتابع؟", ["المذهب المالكي", "المذهب الشافعي", "المذهب الحنفي", "المذهب الحنبلي في المعتمد"], "يرى المالكية أن صوم رمضان المتتابع عبادة واحدة فتكفيه نية واحدة مبيّتة ما لم ينقطع بسفر أو مرض ونحوهما، أما الشافعية والمعتمد عند الحنابلة فتجب النية لكل ليلة."] },

  { id: "fqz-014", s: "fiqh", g: 2, d: 3, t: ["kaffara", "sawm-nullifiers"], src: "al-Bukhārī and Muslim, Kitāb al-Ṣawm (hadith of Abū Hurayra); Ibn Qudāma, al-Mughnī", tr: ["jumhur"],
    en: ["Following the hadith of the man who had intercourse during a day of Ramaḍān, what is the order of the expiation according to the majority?", ["Freeing a slave, then fasting two consecutive months, then feeding sixty poor people", "Feeding sixty poor people, then fasting two months, then freeing a slave", "Fasting three days, then feeding ten poor people, then a sacrifice", "Fasting thirty days, then feeding thirty poor people, then charity"], "In the hadith of Abū Hurayra in al-Bukhārī and Muslim the Prophet ﷺ asked the man in this order: can he free a slave, can he fast two consecutive months, can he feed sixty poor people. The majority treat this order as binding; the Mālikīs allow a free choice."],
    de: ["In welcher Reihenfolge steht nach der Mehrheit die Sühne im Hadith über den Mann, der an einem Ramaḍān-Tag Geschlechtsverkehr hatte?", ["Einen Sklaven befreien, dann zwei aufeinanderfolgende Monate fasten, dann sechzig Arme speisen", "Sechzig Arme speisen, dann zwei Monate fasten, dann einen Sklaven befreien", "Drei Tage fasten, dann zehn Arme speisen, dann ein Opfertier", "Dreißig Tage fasten, dann dreißig Arme speisen, dann Spende"], "Im Hadith von Abū Huraira bei al-Buḫārī und Muslim fragte der Prophet ﷺ den Mann in dieser Reihenfolge: ob er einen Sklaven befreien, zwei Monate hintereinander fasten oder sechzig Arme speisen könne. Die Mehrheit hält diese Reihenfolge für verbindlich; die Malikiten lassen die Wahl."],
    ar: ["ما ترتيب كفارة الجماع في نهار رمضان عند الجمهور بناءً على حديث الرجل الذي واقع أهله؟", ["عتق رقبة، ثم صيام شهرين متتابعين، ثم إطعام ستين مسكينًا", "إطعام ستين مسكينًا، ثم صيام شهرين، ثم العتق", "صيام ثلاثة أيام، ثم إطعام عشرة مساكين، ثم ذبح", "صيام ثلاثين يومًا، ثم إطعام ثلاثين، ثم صدقة"], "في حديث أبي هريرة في الصحيحين سأله النبي ﷺ على هذا الترتيب: هل تجد رقبة؟ هل تستطيع صيام شهرين متتابعين؟ هل تجد إطعام ستين مسكينًا؟ والجمهور على الترتيب، والمالكية على التخيير."] },

  { id: "fqz-015", s: "fiqh", g: 2, d: 3, t: ["fidya", "sawm-exemptions"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṣiyām, on the elderly; Ibn Kathīr, Tafsīr, on 2:184", v: "2:184", w: 17, tr: ["jumhur"],
    en: ["The highlighted word names a compensation. According to the majority, what is due from a very old person who cannot fast and has no hope of becoming able?", ["Feeding one poor person for each day missed", "Making up the days whenever possible", "Fasting two consecutive months", "Nothing at all, since the duty has lapsed"], "The highlighted word is the fidya: feeding a poor person. Ibn ʿAbbās explained the verse as applying to the elderly who cannot fast, and the majority oblige them to feed a poor person for each day. The Mālikīs regard this feeding for the very old as recommended rather than obligatory."],
    de: ["Das hervorgehobene Wort bezeichnet eine Ersatzleistung. Was schuldet nach der Mehrheit ein sehr alter Mensch, der nicht fasten kann und keine Aussicht auf Besserung hat?", ["Für jeden versäumten Tag einen Armen speisen", "Die Tage nachholen, sobald es möglich ist", "Zwei aufeinanderfolgende Monate fasten", "Gar nichts, da die Pflicht entfallen ist"], "Das hervorgehobene Wort ist die Fidya: die Speisung eines Armen. Ibn ʿAbbās bezog die Āya auf alte Menschen, die nicht fasten können, und die Mehrheit verpflichtet sie, für jeden Tag einen Armen zu speisen. Die Malikiten halten diese Speisung beim Greis für empfohlen, nicht für Pflicht."],
    ar: ["الكلمة المظللة تذكر بدلًا عن الصوم. ما الواجب عند الجمهور على الشيخ الكبير العاجز عن الصوم بلا رجاء قدرة؟", ["إطعام مسكين عن كل يوم", "قضاء الأيام متى أمكن", "صيام شهرين متتابعين", "لا شيء عليه لسقوط التكليف"], "الكلمة المظللة هي الفدية وهي طعام مسكين، وقد فسّر ابن عباس الآية بالشيخ الكبير الذي لا يطيق الصوم، فأوجب الجمهور عليه إطعام مسكين عن كل يوم، ويرى المالكية ذلك مستحبًا في حق الهرم."] },

  { id: "fqz-016", s: "fiqh", g: 2, d: 2, t: ["itikaf"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Iʿtikāf; al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 2:187", v: "2:187", w: 53, tr: ["jumhur"],
    en: ["The highlighted word is the place the verse links with iʿtikāf. Where, according to the majority, must a man perform iʿtikāf?", ["In a mosque", "In his own home", "In any clean place", "At the graves of righteous people"], "The verse speaks of those in iʿtikāf in the mosques, so the majority hold that iʿtikāf is only valid in a mosque. The Ḥanafīs allow a woman to perform it in the prayer place of her home."],
    de: ["Das hervorgehobene Wort ist der Ort, den die Āya mit dem Iʿtikāf verbindet. Wo muss ein Mann nach der Mehrheit den Iʿtikāf verrichten?", ["In einer Moschee", "In seinem eigenen Haus", "An jedem reinen Ort", "An den Gräbern rechtschaffener Menschen"], "Die Āya spricht von denen, die sich in den Moscheen zurückziehen; daher ist der Iʿtikāf nach der Mehrheit nur in einer Moschee gültig. Die Ḥanafiten erlauben einer Frau, ihn am Gebetsplatz ihres Hauses zu verrichten."],
    ar: ["الكلمة المظللة هي المكان الذي ربطت به الآية الاعتكاف. أين يصح اعتكاف الرجل عند الجمهور؟", ["في المسجد", "في بيته", "في أي مكان طاهر", "عند قبور الصالحين"], "ذكرت الآية العاكفين في المساجد، فذهب الجمهور إلى أن الاعتكاف لا يصح إلا في مسجد، وأجاز الحنفية للمرأة أن تعتكف في مسجد بيتها."] },

  { id: "fqz-017", s: "fiqh", g: 2, d: 2, t: ["recommended-fasts", "shawwal"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ṣiyām (hadith of Abū Ayyūb al-Anṣārī)",
    en: ["According to the hadith of Abū Ayyūb in Ṣaḥīḥ Muslim, fasting Ramaḍān followed by six days of Shawwāl is like what?", ["Fasting the whole year", "Fasting two months", "Performing an ʿumra", "Fasting the Day of ʿArafa"], "The Prophet ﷺ said that whoever fasts Ramaḍān and follows it with six days of Shawwāl, it is as if he fasted for a lifetime, which the scholars explain as a whole year, each good deed counting tenfold."],
    de: ["Womit ist nach dem Hadith von Abū Aiyūb in Ṣaḥīḥ Muslim das Fasten des Ramaḍān mit anschließenden sechs Tagen des Šauwāl vergleichbar?", ["Mit dem Fasten eines ganzen Jahres", "Mit dem Fasten zweier Monate", "Mit dem Verrichten einer ʿUmra", "Mit dem Fasten am Tag von ʿArafa"], "Der Prophet ﷺ sagte: Wer den Ramaḍān fastet und ihm sechs Tage des Šauwāl folgen lässt, ist wie einer, der immerzu fastet. Die Gelehrten erklären dies als ein ganzes Jahr, da jede gute Tat zehnfach zählt."],
    ar: ["بحسب حديث أبي أيوب في صحيح مسلم، صيام رمضان ثم إتباعه ستًّا من شوال كأنه ماذا؟", ["صيام الدهر", "صيام شهرين", "أداء عمرة", "صيام يوم عرفة"], "قال النبي ﷺ: من صام رمضان ثم أتبعه ستًّا من شوال كان كصيام الدهر، وفسّره العلماء بالسنة كلها لأن الحسنة بعشر أمثالها."] },

  { id: "fqz-018", s: "fiqh", g: 2, d: 3, t: ["recommended-fasts"], src: "al-Nasāʾī and al-Tirmidhī, Kitāb al-Ṣiyām (hadith of Abū Dharr); al-Nawawī, Minhāj al-Ṭālibīn, Bāb Ṣawm al-Taṭawwuʿ",
    en: ["Which days of the lunar month are known as the White Days (ayyām al-bīḍ), on which fasting is recommended?", ["The 13th, 14th and 15th", "The 1st, 2nd and 3rd", "The 10th, 11th and 12th", "The 27th, 28th and 29th"], "The White Days are the 13th, 14th and 15th of the lunar month, when the nights are lit by the full moon. Fasting three days of every month is recommended, and these days are the preferred ones."],
    de: ["Welche Tage des Mondmonats heißen die Weißen Tage (aiyām al-bīḍ), an denen das Fasten empfohlen ist?", ["Der 13., 14. und 15.", "Der 1., 2. und 3.", "Der 10., 11. und 12.", "Der 27., 28. und 29."], "Die Weißen Tage sind der 13., 14. und 15. des Mondmonats, wenn die Nächte vom Vollmond erhellt sind. Drei Tage in jedem Monat zu fasten ist empfohlen, und diese Tage sind dafür die bevorzugten."],
    ar: ["ما الأيام البيض التي يستحب صيامها من الشهر القمري؟", ["الثالث عشر والرابع عشر والخامس عشر", "الأول والثاني والثالث", "العاشر والحادي عشر والثاني عشر", "السابع والعشرون والثامن والعشرون والتاسع والعشرون"], "الأيام البيض هي الثالث عشر والرابع عشر والخامس عشر، سميت بذلك لابيضاض لياليها بالقمر، ويستحب صيام ثلاثة أيام من كل شهر وأفضلها هذه."] },

  { id: "fqz-019", s: "fiqh", g: 3, d: 3, t: ["kaffara", "school-differences"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣiyām, on the expiation", tr: ["comparative", "hanafi", "maliki", "shafii", "hanbali"],
    en: ["Which statement correctly describes the disagreement about deliberately eating or drinking during a day of Ramaḍān?", ["Ḥanafīs and Mālikīs require make-up and expiation; Shāfiʿīs and Ḥanbalīs require make-up only", "Shāfiʿīs and Ḥanbalīs require make-up and expiation; Ḥanafīs and Mālikīs require make-up only", "All four schools require make-up and expiation", "All four schools require make-up only, without expiation"], "The Ḥanafīs and Mālikīs extend the expiation to any deliberate violation of the Ramaḍān fast, reasoning from its sanctity. The Shāfiʿīs and Ḥanbalīs restrict it to intercourse, the case named in the hadith, so deliberate eating requires make-up, repentance and no expiation."],
    de: ["Welche Aussage beschreibt den Meinungsunterschied über absichtliches Essen oder Trinken an einem Ramaḍān-Tag richtig?", ["Ḥanafiten und Malikiten verlangen Nachholen und Sühne, Šāfiʿiten und Ḥanbaliten nur Nachholen", "Šāfiʿiten und Ḥanbaliten verlangen Nachholen und Sühne, Ḥanafiten und Malikiten nur Nachholen", "Alle vier Schulen verlangen Nachholen und Sühne", "Alle vier Schulen verlangen nur Nachholen ohne Sühne"], "Ḥanafiten und Malikiten dehnen die Sühne auf jede absichtliche Verletzung des Ramaḍān-Fastens aus, begründet mit seiner Unantastbarkeit. Šāfiʿiten und Ḥanbaliten beschränken sie auf den im Hadith genannten Geschlechtsverkehr; absichtliches Essen verlangt daher Nachholen und Reue, aber keine Sühne."],
    ar: ["أيّ العبارات تصف الخلاف في الأكل أو الشرب عمدًا في نهار رمضان وصفًا صحيحًا؟", ["الحنفية والمالكية: القضاء والكفارة، والشافعية والحنابلة: القضاء فقط", "الشافعية والحنابلة: القضاء والكفارة، والحنفية والمالكية: القضاء فقط", "المذاهب الأربعة: القضاء والكفارة", "المذاهب الأربعة: القضاء فقط بلا كفارة"], "عدّى الحنفية والمالكية الكفارة إلى كل انتهاك عمدي لحرمة رمضان، وقصرها الشافعية والحنابلة على الجماع الوارد في الحديث، فعلى الآكل عمدًا عندهم القضاء والتوبة دون كفارة."] },

  { id: "fqz-020", s: "fiqh", g: 3, d: 4, t: ["sawm-nullifiers", "school-differences"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṣiyām, on cupping; Ibn Rushd, Bidāyat al-Mujtahid", tr: ["hanbali", "comparative"],
    en: ["Which school holds that cupping (ḥijāma) breaks the fast of both the one who is cupped and the one who performs it?", ["The Ḥanbalī school", "The Ḥanafī school", "The Mālikī school", "The Shāfiʿī school"], "The Ḥanbalīs act on the hadith that the cupper and the cupped have both broken their fast. The other three schools hold that it does not break the fast, citing the report that the Prophet ﷺ was cupped while fasting, though it is disliked for someone it weakens."],
    de: ["Welche Schule hält, dass das Schröpfen (Ḥiǧāma) das Fasten sowohl des Geschröpften als auch des Schröpfenden bricht?", ["Die ḥanbalitische Schule", "Die ḥanafitische Schule", "Die malikitische Schule", "Die šāfiʿitische Schule"], "Die Ḥanbaliten folgen dem Hadith, dass der Schröpfer und der Geschröpfte ihr Fasten gebrochen haben. Die anderen drei Schulen halten, dass es das Fasten nicht bricht, unter Berufung auf den Bericht, dass sich der Prophet ﷺ fastend schröpfen ließ; für den, den es schwächt, ist es jedoch verpönt."],
    ar: ["أيّ مذهب يرى أن الحجامة تفطّر الحاجم والمحجوم معًا؟", ["المذهب الحنبلي", "المذهب الحنفي", "المذهب المالكي", "المذهب الشافعي"], "أخذ الحنابلة بحديث: أفطر الحاجم والمحجوم، وذهب الثلاثة إلى أنها لا تفطّر استدلالًا بأن النبي ﷺ احتجم وهو صائم، مع كراهتها لمن تُضعفه."] },

  { id: "fqz-021", s: "fiqh", g: 3, d: 3, t: ["qada", "fidya", "school-differences"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣiyām; Ibn Qudāma, al-Mughnī", tr: ["jumhur", "hanafi", "comparative"],
    en: ["Someone delays making up Ramaḍān days without excuse until the next Ramaḍān arrives. Which statement describes the positions correctly?", ["The majority require make-up plus feeding a poor person per day; the Ḥanafīs require make-up only", "The Ḥanafīs require make-up plus feeding; the majority require make-up only", "All schools say the days lapse and only repentance is due", "All schools require two consecutive months as expiation"], "Mālik, al-Shāfiʿī and Aḥmad require the make-up together with feeding one poor person for each day, following reports from Companions such as Abū Hurayra and Ibn ʿAbbās. Abū Ḥanīfa requires only the make-up, since the verse mentions make-up without a time limit."],
    de: ["Jemand schiebt das Nachholen von Ramaḍān-Tagen ohne Grund auf, bis der nächste Ramaḍān beginnt. Welche Aussage beschreibt die Positionen richtig?", ["Die Mehrheit verlangt Nachholen und die Speisung eines Armen pro Tag, die Ḥanafiten nur Nachholen", "Die Ḥanafiten verlangen Nachholen und Speisung, die Mehrheit nur Nachholen", "Alle Schulen sagen, die Tage verfallen und nur Reue ist fällig", "Alle Schulen verlangen zwei aufeinanderfolgende Monate als Sühne"], "Mālik, aš-Šāfiʿī und Aḥmad verlangen das Nachholen samt Speisung eines Armen für jeden Tag, gestützt auf Berichte von Gefährten wie Abū Huraira und Ibn ʿAbbās. Abū Ḥanīfa verlangt nur das Nachholen, da die Āya das Nachholen ohne Frist nennt."],
    ar: ["من أخّر قضاء رمضان بلا عذر حتى دخل رمضان آخر، فأيّ العبارات تصف الأقوال صحيحًا؟", ["الجمهور: القضاء مع إطعام مسكين عن كل يوم، والحنفية: القضاء فقط", "الحنفية: القضاء مع الإطعام، والجمهور: القضاء فقط", "الجميع: تسقط الأيام وتكفي التوبة", "الجميع: صيام شهرين متتابعين كفارة"], "أوجب مالك والشافعي وأحمد القضاء مع إطعام مسكين عن كل يوم أخذًا بآثار الصحابة كأبي هريرة وابن عباس، وأوجب أبو حنيفة القضاء وحده لأن الآية ذكرت القضاء دون توقيت."] },

  { id: "fqz-022", s: "fiqh", g: 3, d: 4, t: ["itikaf", "school-differences"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Iʿtikāf; Ibn Qudāma, al-Mughnī, Kitāb al-Iʿtikāf", tr: ["comparative", "hanafi", "maliki", "shafii", "hanbali"],
    en: ["Which schools make fasting a condition of iʿtikāf (at least of an iʿtikāf that has been vowed)?", ["The Ḥanafī and Mālikī schools", "The Shāfiʿī and Ḥanbalī schools", "The Ḥanafī and Shāfiʿī schools", "The Mālikī and Ḥanbalī schools"], "The Mālikīs require fasting for every iʿtikāf, and the Ḥanafīs require it for a vowed iʿtikāf. The Shāfiʿīs and Ḥanbalīs do not make it a condition, citing ʿUmar's vow to spend a night in iʿtikāf, since a night has no fast."],
    de: ["Welche Schulen machen das Fasten zur Bedingung des Iʿtikāf (zumindest des gelobten Iʿtikāf)?", ["Die ḥanafitische und die malikitische Schule", "Die šāfiʿitische und die ḥanbalitische Schule", "Die ḥanafitische und die šāfiʿitische Schule", "Die malikitische und die ḥanbalitische Schule"], "Die Malikiten verlangen das Fasten bei jedem Iʿtikāf, die Ḥanafiten beim gelobten Iʿtikāf. Šāfiʿiten und Ḥanbaliten machen es nicht zur Bedingung und verweisen auf ʿUmars Gelübde, eine Nacht im Iʿtikāf zu verbringen, denn in der Nacht wird nicht gefastet."],
    ar: ["أيّ المذاهب يشترط الصوم للاعتكاف (على الأقل للاعتكاف المنذور)؟", ["الحنفية والمالكية", "الشافعية والحنابلة", "الحنفية والشافعية", "المالكية والحنابلة"], "يشترط المالكية الصوم لكل اعتكاف، ويشترطه الحنفية للاعتكاف المنذور، ولا يشترطه الشافعية والحنابلة استدلالًا بنذر عمر أن يعتكف ليلة، والليل ليس محلًا للصوم."] },

  { id: "fqz-023", s: "fiqh", g: 3, d: 4, t: ["zakat-al-fitr", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Bāb Ṣadaqat al-Fiṭr; Ibn Qudāma, al-Mughnī, Bāb Zakāt al-Fiṭr", tr: ["hanafi", "jumhur", "comparative"],
    en: ["Which statement correctly describes the disagreement about paying Zakāt al-Fiṭr in money instead of food?", ["The Ḥanafīs permit paying its value; the Mālikīs, Shāfiʿīs and Ḥanbalīs require the foodstuffs named in the hadith", "The Shāfiʿīs permit paying its value; the other three schools require food", "All four schools prefer money and permit food only as a substitute", "All four schools forbid food and require money"], "The Ḥanafīs see the purpose as enriching the poor on the day of ʿĪd and so accept the value. The majority hold to the wording of the hadith, which specifies a ṣāʿ of food, and do not accept value in its place in their relied positions."],
    de: ["Welche Aussage beschreibt den Meinungsunterschied über die Zahlung der Zakāt al-Fiṭr in Geld statt in Nahrung richtig?", ["Die Ḥanafiten erlauben den Gegenwert; Malikiten, Šāfiʿiten und Ḥanbaliten verlangen die im Hadith genannten Lebensmittel", "Die Šāfiʿiten erlauben den Gegenwert; die anderen drei Schulen verlangen Nahrung", "Alle vier Schulen bevorzugen Geld und erlauben Nahrung nur ersatzweise", "Alle vier Schulen verbieten Nahrung und verlangen Geld"], "Die Ḥanafiten sehen den Zweck darin, die Armen am ʿĪd-Tag unabhängig zu machen, und akzeptieren daher den Gegenwert. Die Mehrheit hält sich an den Wortlaut des Hadith, der ein Ṣāʿ Nahrung festlegt, und lässt den Gegenwert in ihren maßgeblichen Ansichten nicht an dessen Stelle treten."],
    ar: ["أيّ العبارات تصف الخلاف في إخراج زكاة الفطر نقودًا بدل الطعام وصفًا صحيحًا؟", ["يجيز الحنفية إخراج القيمة، ويشترط المالكية والشافعية والحنابلة الأصناف المنصوصة", "يجيز الشافعية القيمة، ويشترط الثلاثة الطعام", "يفضّل الأربعة النقود ويجيزون الطعام بدلًا", "يمنع الأربعة الطعام ويوجبون النقود"], "نظر الحنفية إلى المقصود وهو إغناء الفقير يوم العيد فأجازوا القيمة، وتمسّك الجمهور بلفظ الحديث المنصوص على الصاع من الطعام فلم يجيزوا القيمة في المعتمد عندهم."] },

  { id: "fqz-024", s: "fiqh", g: 3, d: 3, t: ["zakat-al-fitr", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Bāb Ṣadaqat al-Fiṭr; al-Nawawī, Minhāj al-Ṭālibīn, Bāb Zakāt al-Fiṭr", tr: ["comparative", "hanafi", "shafii", "hanbali"],
    en: ["At what moment does Zakāt al-Fiṭr become obligatory?", ["Shāfiʿīs and Ḥanbalīs: at sunset on the last day of Ramaḍān; Ḥanafīs: at dawn on the day of ʿĪd", "Ḥanafīs: at sunset on the last day of Ramaḍān; Shāfiʿīs and Ḥanbalīs: at dawn on the day of ʿĪd", "All schools: at the start of Ramaḍān", "All schools: after the ʿĪd prayer"], "The disagreement matters for a child born or a person who dies in the night before ʿĪd. The Shāfiʿīs and Ḥanbalīs link the obligation to the end of Ramaḍān at sunset, the Ḥanafīs to the dawn of the day of breaking the fast; the Mālikīs have two narrations."],
    de: ["Zu welchem Zeitpunkt wird die Zakāt al-Fiṭr verpflichtend?", ["Šāfiʿiten und Ḥanbaliten: bei Sonnenuntergang am letzten Ramaḍān-Tag; Ḥanafiten: bei der Morgendämmerung des ʿĪd-Tages", "Ḥanafiten: bei Sonnenuntergang am letzten Ramaḍān-Tag; Šāfiʿiten und Ḥanbaliten: bei der Morgendämmerung des ʿĪd-Tages", "Alle Schulen: zu Beginn des Ramaḍān", "Alle Schulen: nach dem ʿĪd-Gebet"], "Der Unterschied ist bedeutsam für ein Kind, das in der Nacht vor dem ʿĪd geboren wird, oder jemanden, der in dieser Nacht stirbt. Šāfiʿiten und Ḥanbaliten knüpfen die Pflicht an das Ende des Ramaḍān bei Sonnenuntergang, die Ḥanafiten an die Morgendämmerung des Fastenbrechen-Tages; bei den Malikiten gibt es zwei Überlieferungen."],
    ar: ["متى تجب زكاة الفطر؟", ["الشافعية والحنابلة: بغروب شمس آخر يوم من رمضان، والحنفية: بطلوع فجر يوم العيد", "الحنفية: بغروب شمس آخر يوم من رمضان، والشافعية والحنابلة: بطلوع فجر يوم العيد", "الجميع: بدخول رمضان", "الجميع: بعد صلاة العيد"], "تظهر ثمرة الخلاف فيمن وُلد أو مات ليلة العيد؛ فالشافعية والحنابلة يعلّقون الوجوب بغروب شمس آخر رمضان، والحنفية بطلوع فجر يوم الفطر، وللمالكية روايتان."] },

  { id: "fqz-025", s: "fiqh", g: 4, d: 5, t: ["sawm-exemptions", "fidya", "school-differences"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣiyām; Khalīl, al-Mukhtaṣar, Bāb al-Ṣiyām", tr: ["comparative", "hanafi", "maliki", "shafii", "hanbali"],
    en: ["A pregnant woman and a nursing mother break the fast fearing only for the child. Which statement describes the schools correctly?", ["Ḥanafīs: make-up only; Shāfiʿīs and Ḥanbalīs: make-up and feeding; Mālikīs: feeding for the nursing mother but not the pregnant woman", "Ḥanafīs: make-up and feeding for both; Shāfiʿīs and Ḥanbalīs: make-up only; Mālikīs: feeding for the pregnant woman only", "All four schools: feeding only, with no make-up", "All four schools: make-up only, with no feeding"], "Ibn Rushd explains the disagreement by whether such women resemble the sick (make-up only) or those able to fast with hardship (feeding). The Ḥanafīs treat both like the sick; the Shāfiʿīs and Ḥanbalīs require both make-up and feeding when the fear is for the child; the Mālikīs class pregnancy as illness but require feeding from the nursing mother."],
    de: ["Eine Schwangere und eine Stillende brechen das Fasten nur aus Sorge um das Kind. Welche Aussage beschreibt die Schulen richtig?", ["Ḥanafiten: nur Nachholen; Šāfiʿiten und Ḥanbaliten: Nachholen und Speisung; Malikiten: Speisung für die Stillende, nicht für die Schwangere", "Ḥanafiten: Nachholen und Speisung für beide; Šāfiʿiten und Ḥanbaliten: nur Nachholen; Malikiten: Speisung nur für die Schwangere", "Alle vier Schulen: nur Speisung, kein Nachholen", "Alle vier Schulen: nur Nachholen, keine Speisung"], "Ibn Rušd führt den Unterschied darauf zurück, ob diese Frauen dem Kranken (nur Nachholen) oder dem, der nur mit Mühe fasten kann (Speisung), gleichen. Die Ḥanafiten behandeln beide wie Kranke; Šāfiʿiten und Ḥanbaliten verlangen bei Sorge um das Kind Nachholen und Speisung; die Malikiten stufen die Schwangerschaft als Krankheit ein, verlangen von der Stillenden aber die Speisung."],
    ar: ["أفطرت الحامل والمرضع خوفًا على الولد فقط، فأيّ العبارات تصف المذاهب صحيحًا؟", ["الحنفية: القضاء فقط، والشافعية والحنابلة: القضاء والإطعام، والمالكية: الإطعام على المرضع دون الحامل", "الحنفية: القضاء والإطعام عليهما، والشافعية والحنابلة: القضاء فقط، والمالكية: الإطعام على الحامل فقط", "الأربعة: الإطعام فقط بلا قضاء", "الأربعة: القضاء فقط بلا إطعام"], "ردّ ابن رشد الخلاف إلى تردّدهما بين شبه المريض فعليهما القضاء فقط، وشبه من يطيق الصوم بمشقة فعليهما الإطعام؛ فجعلهما الحنفية كالمريض، وأوجب الشافعية والحنابلة القضاء والإطعام عند الخوف على الولد، وألحق المالكية الحامل بالمريض وأوجبوا الإطعام على المرضع."] },

  { id: "fqz-026", s: "fiqh", g: 4, d: 4, t: ["kaffara", "school-differences"], src: "Khalīl, al-Mukhtaṣar, Bāb al-Ṣiyām, on the expiation; Ibn Rushd, Bidāyat al-Mujtahid", tr: ["maliki", "comparative"],
    en: ["How does the Mālikī school treat the three options of the Ramaḍān expiation?", ["As a free choice, with feeding sixty poor people the best option", "As a strict order beginning with freeing a slave", "As a strict order beginning with fasting two months", "As a free choice, with fasting two months the only valid option today"], "Khalīl's Mukhtaṣar treats the expiation as a choice between feeding sixty poor people, fasting two consecutive months and freeing a slave, and names feeding as the best because its benefit reaches many. The majority read the hadith as prescribing a fixed order."],
    de: ["Wie behandelt die malikitische Schule die drei Möglichkeiten der Ramaḍān-Sühne?", ["Als freie Wahl, wobei die Speisung von sechzig Armen am besten ist", "Als feste Reihenfolge, beginnend mit der Sklavenbefreiung", "Als feste Reihenfolge, beginnend mit zwei Monaten Fasten", "Als freie Wahl, wobei heute nur zwei Monate Fasten gültig sind"], "Ḫalīls Muḫtaṣar behandelt die Sühne als Wahl zwischen der Speisung von sechzig Armen, zwei aufeinanderfolgenden Fastenmonaten und der Sklavenbefreiung und nennt die Speisung als die beste, weil ihr Nutzen viele erreicht. Die Mehrheit versteht den Hadith als feste Reihenfolge."],
    ar: ["كيف يتعامل المذهب المالكي مع خصال كفارة رمضان الثلاث؟", ["على التخيير، والإطعام أفضلها", "على الترتيب بدءًا بالعتق", "على الترتيب بدءًا بصيام شهرين", "على التخيير، ولا يصح اليوم إلا صيام شهرين"], "جعل خليل في مختصره الكفارة على التخيير بين إطعام ستين مسكينًا وصيام شهرين متتابعين والعتق، ونصّ على أن الإطعام أفضل لتعدّي نفعه، وحمل الجمهور الحديث على الترتيب."] },

  { id: "fqz-027", s: "fiqh", g: 4, d: 5, t: ["sawm-intention", "school-differences"], src: "Khalīl, al-Mukhtaṣar, Bāb al-Ṣiyām; Ibn Qudāma, al-Mughnī, Kitāb al-Ṣiyām, on the intention", tr: ["maliki", "comparative"],
    en: ["A person decides in the late morning to begin a voluntary fast, having eaten nothing since dawn. Which school does NOT consider this fast valid?", ["The Mālikī school", "The Ḥanafī school", "The Shāfiʿī school", "The Ḥanbalī school"], "The Mālikīs require the intention to be made during the night for every fast, voluntary or obligatory, applying the general hadith of Ḥafṣa. The other three schools accept a daytime intention for a voluntary fast, citing ʿĀʾisha's report in Ṣaḥīḥ Muslim that the Prophet ﷺ, finding no food, said he would then fast."],
    de: ["Jemand beschließt am späten Vormittag, ein freiwilliges Fasten zu beginnen, und hat seit der Morgendämmerung nichts gegessen. Welche Schule hält dieses Fasten NICHT für gültig?", ["Die malikitische Schule", "Die ḥanafitische Schule", "Die šāfiʿitische Schule", "Die ḥanbalitische Schule"], "Die Malikiten verlangen für jedes Fasten, ob freiwillig oder Pflicht, die Absicht in der Nacht und wenden den allgemeinen Hadith von Ḥafṣa an. Die anderen drei Schulen akzeptieren beim freiwilligen Fasten eine Absicht am Tag und verweisen auf ʿĀʾišas Bericht in Ṣaḥīḥ Muslim, dass der Prophet ﷺ, als er keine Speise fand, sagte, dann faste er."],
    ar: ["نوى شخص صوم تطوّع في الضحى ولم يتناول شيئًا منذ الفجر، فأيّ مذهب لا يصحّح هذا الصوم؟", ["المذهب المالكي", "المذهب الحنفي", "المذهب الشافعي", "المذهب الحنبلي"], "يشترط المالكية تبييت النية في كل صوم فرضًا كان أو نفلًا عملًا بعموم حديث حفصة، وأجاز الثلاثة نية النفل نهارًا لحديث عائشة في صحيح مسلم أن النبي ﷺ لما لم يجد طعامًا قال: فإني إذن صائم."] },

  { id: "fqz-028", s: "fiqh", g: 3, d: 4, t: ["forbidden-fasts", "tamattu"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Ṣawm, on fasting the days of tashrīq",
    en: ["According to the report of ʿĀʾisha and Ibn ʿUmar in Ṣaḥīḥ al-Bukhārī, who was granted a concession to fast on the days of tashrīq?", ["A pilgrim on tamattuʿ or qirān who finds no sacrificial animal", "A person making up missed Ramaḍān days", "Anyone who has vowed to fast", "A person observing the six days of Shawwāl"], "They reported that no concession was given to fast the days of tashrīq except for someone who finds no hady. This is why the Mālikīs and one narration from Aḥmad allow the pilgrim without hady to fast the three days of ḥajj then, while the Ḥanafīs and the new Shāfiʿī view do not."],
    de: ["Wem wurde nach dem Bericht von ʿĀʾiša und Ibn ʿUmar in Ṣaḥīḥ al-Buḫārī eine Erleichterung gewährt, an den Tašrīq-Tagen zu fasten?", ["Einem Pilger mit Tamattuʿ oder Qirān, der kein Opfertier findet", "Jemandem, der versäumte Ramaḍān-Tage nachholt", "Jedem, der ein Fastengelübde abgelegt hat", "Jemandem, der die sechs Tage des Šauwāl fastet"], "Sie berichteten, dass niemandem erlaubt wurde, an den Tašrīq-Tagen zu fasten, außer dem, der kein Hady findet. Deshalb erlauben die Malikiten und eine Überlieferung von Aḥmad dem Pilger ohne Hady, dann die drei Tage des Ḥaǧǧ zu fasten, während die Ḥanafiten und die neue šāfiʿitische Ansicht es nicht erlauben."],
    ar: ["بحسب أثر عائشة وابن عمر في صحيح البخاري، لمن رُخّص في صيام أيام التشريق؟", ["للمتمتع أو القارن الذي لم يجد الهدي", "لمن يقضي أيامًا من رمضان", "لكل من نذر صومًا", "لمن يصوم ستًّا من شوال"], "قالا: لم يُرخّص في أيام التشريق أن يُصمن إلا لمن لم يجد الهدي؛ ولهذا أجاز المالكية وأحمد في رواية للمتمتع العادم للهدي صيام الثلاثة فيها، ومنعه الحنفية والشافعي في الجديد."] },

  { id: "fqz-029", s: "fiqh", g: 4, d: 4, t: ["recommended-fasts", "shawwal", "school-differences"], src: "Mālik, al-Muwaṭṭaʾ, Kitāb al-Ṣiyām; Ibn Rushd, Bidāyat al-Mujtahid", tr: ["maliki", "comparative"],
    en: ["Which imam is reported in his own work to have disliked fasting the six days of Shawwāl, fearing that people would think them part of Ramaḍān?", ["Mālik ibn Anas in al-Muwaṭṭaʾ", "al-Shāfiʿī in al-Umm", "Aḥmad ibn Ḥanbal in his Musnad", "Abū Yūsuf in Kitāb al-Kharāj"], "Mālik stated in al-Muwaṭṭaʾ that he had not seen the people of knowledge fast them and disliked it lest they be joined to Ramaḍān. Later Mālikīs restricted the dislike to fasting them immediately and publicly, while the Shāfiʿīs and Ḥanbalīs consider them recommended based on the hadith in Ṣaḥīḥ Muslim."],
    de: ["Von welchem Imam wird in seinem eigenen Werk berichtet, dass er das Fasten der sechs Šauwāl-Tage missbilligte, aus Sorge, man könnte sie für einen Teil des Ramaḍān halten?", ["Mālik ibn Anas im Muwaṭṭaʾ", "aš-Šāfiʿī in al-Umm", "Aḥmad ibn Ḥanbal in seinem Musnad", "Abū Yūsuf im Kitāb al-Ḫarāǧ"], "Mālik erklärte im Muwaṭṭaʾ, er habe die Gelehrten sie nicht fasten sehen, und missbilligte es, damit sie nicht dem Ramaḍān angehängt würden. Spätere Malikiten beschränkten die Missbilligung auf das unmittelbare und öffentliche Fasten, während Šāfiʿiten und Ḥanbaliten sie aufgrund des Hadith in Ṣaḥīḥ Muslim für empfohlen halten."],
    ar: ["أيّ إمام نُقل عنه في كتابه كراهة صيام ستٍّ من شوال خشية أن تُلحق برمضان؟", ["مالك بن أنس في الموطأ", "الشافعي في الأم", "أحمد بن حنبل في المسند", "أبو يوسف في كتاب الخراج"], "ذكر مالك في الموطأ أنه لم يرَ أحدًا من أهل العلم يصومها، وكرهها خشية أن يُلحق برمضان ما ليس منه، وقيّد متأخرو المالكية الكراهة بوصلها وإظهارها، واستحبها الشافعية والحنابلة لحديث مسلم."] },

  { id: "fqz-030", s: "fiqh", g: 2, d: 3, t: ["sawm-exemptions", "travel"], src: "al-Bukhārī and Muslim, Kitāb al-Ṣawm (hadith of Anas); Ibn Qudāma, al-Mughnī", tr: ["jumhur"],
    en: ["What do the hadith of the Companions' travels with the Prophet ﷺ show about fasting on a journey?", ["Both fasting and breaking the fast are permitted, and neither group blamed the other", "Fasting on a journey is invalid and must be repeated", "Breaking the fast on a journey requires an expiation", "Only those travelling on foot may break the fast"], "Anas reported in al-Bukhārī and Muslim that on journeys with the Prophet ﷺ some fasted and some did not, and neither criticised the other. The majority therefore hold that the traveller may choose, while differing on which is better in a given situation."],
    de: ["Was zeigen die Hadithe über die Reisen der Gefährten mit dem Propheten ﷺ zum Fasten auf Reisen?", ["Fasten und Fastenbrechen sind beide erlaubt, und keine Gruppe tadelte die andere", "Das Fasten auf Reisen ist ungültig und muss wiederholt werden", "Das Fastenbrechen auf Reisen verlangt eine Sühne", "Nur wer zu Fuß reist, darf das Fasten brechen"], "Anas berichtete bei al-Buḫārī und Muslim, dass auf Reisen mit dem Propheten ﷺ einige fasteten und andere nicht, ohne dass die einen die anderen tadelten. Die Mehrheit lässt dem Reisenden daher die Wahl und unterscheidet nur darin, was in einer bestimmten Lage besser ist."],
    ar: ["ماذا تدل عليه أحاديث سفر الصحابة مع النبي ﷺ في حكم الصوم في السفر؟", ["يجوز الصوم والفطر، ولم يعب أحد الفريقين على الآخر", "الصوم في السفر باطل تجب إعادته", "الفطر في السفر يوجب الكفارة", "لا يفطر إلا المسافر ماشيًا"], "روى أنس في الصحيحين أنهم سافروا مع النبي ﷺ فلم يعب الصائم على المفطر ولا المفطر على الصائم، فذهب الجمهور إلى التخيير مع اختلافهم في الأفضل بحسب الحال."] },

  // ───────────── Zakāt ─────────────
  { id: "fqz-031", s: "fiqh", g: 1, d: 1, t: ["zakat-rates", "zakat-money"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Zakāt, on gold and silver", tr: ["ijma"],
    en: ["What is the rate of zakāt on gold, silver and cash savings that reach the niṣāb and complete a year?", ["One fortieth (2.5 %)", "One tenth (10 %)", "One twentieth (5 %)", "One fifth (20 %)"], "Zakāt on gold, silver and money is a quarter of a tenth, i.e. one fortieth. Ten and five per cent apply to crops, and one fifth to buried treasure (rikāz)."],
    de: ["Wie hoch ist der Zakāt-Satz auf Gold, Silber und Geldersparnisse, die den Niṣāb erreichen und ein Jahr vollenden?", ["Ein Vierzigstel (2,5 %)", "Ein Zehntel (10 %)", "Ein Zwanzigstel (5 %)", "Ein Fünftel (20 %)"], "Die Zakāt auf Gold, Silber und Geld beträgt ein Viertel des Zehnten, also ein Vierzigstel. Zehn und fünf Prozent gelten für Feldfrüchte, ein Fünftel für vergrabene Schätze (Rikāz)."],
    ar: ["ما مقدار الزكاة الواجبة في الذهب والفضة والنقود المدّخرة إذا بلغت النصاب وحال عليها الحول؟", ["ربع العشر (2.5 %)", "العشر (10 %)", "نصف العشر (5 %)", "الخُمس (20 %)"], "زكاة الذهب والفضة والنقود ربع العشر أي جزء من أربعين، أما العشر ونصفه ففي الزروع والثمار، والخمس في الركاز."] },

  { id: "fqz-032", s: "fiqh", g: 1, d: 1, t: ["zakat-conditions", "hawl"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Zakāt, on the ḥawl",
    en: ["What is the ḥawl in the law of zakāt?", ["The full lunar year that wealth must remain in one's ownership", "The minimum amount of wealth on which zakāt is due", "The share given to zakāt collectors", "The day of harvest for crops"], "The ḥawl is the passing of one lunar year over the niṣāb in one's ownership; it is a condition for money, trade goods and livestock. The minimum amount is the niṣāb, and crops are due at harvest without a ḥawl."],
    de: ["Was ist der Ḥaul im Recht der Zakāt?", ["Das volle Mondjahr, das ein Vermögen im eigenen Besitz bleiben muss", "Der Mindestbetrag, ab dem Zakāt fällig wird", "Der Anteil der Zakāt-Einsammler", "Der Erntetag bei Feldfrüchten"], "Der Ḥaul ist das Verstreichen eines Mondjahres, während der Niṣāb im eigenen Besitz ist; er ist Bedingung bei Geld, Handelsware und Vieh. Der Mindestbetrag ist der Niṣāb, und Feldfrüchte sind ohne Ḥaul bei der Ernte fällig."],
    ar: ["ما المراد بالحول في باب الزكاة؟", ["مضيّ سنة قمرية كاملة على المال في الملك", "أقل قدر من المال تجب فيه الزكاة", "نصيب العاملين على الزكاة", "يوم حصاد الزروع"], "الحول مرور سنة قمرية على النصاب في ملك صاحبه، وهو شرط في النقدين وعروض التجارة والماشية، أما أقل القدر فهو النصاب، والزروع تجب يوم الحصاد بلا حول."] },

  { id: "fqz-033", s: "fiqh", g: 1, d: 1, t: ["zakat-recipients"], src: "Ibn Kathīr, Tafsīr, on 9:60", v: "9:60", tr: ["ijma"],
    en: ["How many categories of zakāt recipients does the verse shown list?", ["Eight", "Six", "Seven", "Ten"], "The verse names eight categories: the poor, the needy, those employed to collect it, those whose hearts are to be reconciled, the freeing of captives, debtors, the cause of Allah and the stranded traveller."],
    de: ["Wie viele Gruppen von Zakāt-Empfängern zählt die angezeigte Āya auf?", ["Acht", "Sechs", "Sieben", "Zehn"], "Die Āya nennt acht Gruppen: die Armen, die Bedürftigen, die mit der Einsammlung Betrauten, die, deren Herzen gewonnen werden sollen, den Freikauf von Unfreien, die Verschuldeten, den Weg Allahs und den gestrandeten Reisenden."],
    ar: ["كم صنفًا من مستحقي الزكاة تذكر الآية المعروضة؟", ["ثمانية", "ستة", "سبعة", "عشرة"], "ذكرت الآية ثمانية أصناف: الفقراء، والمساكين، والعاملين عليها، والمؤلفة قلوبهم، وفي الرقاب، والغارمين، وفي سبيل الله، وابن السبيل."] },

  { id: "fqz-034", s: "fiqh", g: 1, d: 2, t: ["zakat-recipients"], src: "Ibn Kathīr, Tafsīr, on 9:60; Ibn Qudāma, al-Mughnī, Bāb Ahl al-Zakāt", v: "9:60", w: 15,
    en: ["The highlighted word, together with the word after it, names one of the categories of zakāt. Who is meant?", ["A traveller cut off from his wealth", "A wealthy merchant on a business trip", "A pilgrim who has enough provisions", "A guest staying in the payer's house"], "Ibn al-sabīl is the traveller who has run out of means on his journey, even if he is wealthy at home; he receives what brings him to his destination. A traveller with sufficient means is not included."],
    de: ["Das hervorgehobene Wort nennt zusammen mit dem folgenden Wort eine der Zakāt-Gruppen. Wer ist gemeint?", ["Ein Reisender, der von seinem Vermögen abgeschnitten ist", "Ein wohlhabender Kaufmann auf Geschäftsreise", "Ein Pilger mit ausreichendem Reiseproviant", "Ein Gast im Haus des Zakāt-Zahlers"], "Ibn as-sabīl ist der Reisende, dem unterwegs die Mittel ausgegangen sind, selbst wenn er daheim wohlhabend ist; er erhält, was ihn an sein Ziel bringt. Ein Reisender mit ausreichenden Mitteln gehört nicht dazu."],
    ar: ["الكلمة المظللة وما بعدها تذكر صنفًا من أصناف الزكاة، فمن المقصود؟", ["المسافر المنقطع عن ماله", "التاجر الغني في سفر تجارة", "الحاج الذي معه نفقة كافية", "الضيف النازل في بيت المزكّي"], "ابن السبيل هو المسافر الذي انقطعت به نفقته في سفره وإن كان غنيًا في بلده، فيُعطى ما يبلّغه مقصده، أما المسافر الواجد لنفقته فلا يدخل فيه."] },

  { id: "fqz-035", s: "fiqh", g: 1, d: 2, t: ["nisab", "zakat-money"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Zakāt, on the niṣāb of gold; Ibn Rushd, Bidāyat al-Mujtahid", tr: ["jumhur"],
    en: ["In the classical units used by the jurists, what is the niṣāb of gold?", ["Twenty mithqāls (dīnārs)", "Two hundred mithqāls", "Five mithqāls", "Forty mithqāls"], "The jurists state the niṣāb of gold as twenty mithqāls and that of silver as two hundred dirhams (five ūqiyas). Forty is the niṣāb of sheep and five the niṣāb of camels."],
    de: ["Wie hoch ist der Niṣāb von Gold in den klassischen Einheiten der Juristen?", ["Zwanzig Miṯqāl (Dīnār)", "Zweihundert Miṯqāl", "Fünf Miṯqāl", "Vierzig Miṯqāl"], "Die Juristen geben den Niṣāb von Gold mit zwanzig Miṯqāl und den von Silber mit zweihundert Dirham (fünf Ūqiya) an. Vierzig ist der Niṣāb bei Schafen, fünf bei Kamelen."],
    ar: ["ما نصاب الذهب بالوحدات التي يذكرها الفقهاء؟", ["عشرون مثقالًا (دينارًا)", "مئتا مثقال", "خمسة مثاقيل", "أربعون مثقالًا"], "نصاب الذهب عند الفقهاء عشرون مثقالًا، ونصاب الفضة مئتا درهم أي خمس أواق، أما الأربعون فنصاب الغنم، والخمس نصاب الإبل."] },

  { id: "fqz-036", s: "fiqh", g: 1, d: 2, t: ["zakat-crops", "zakat-rates"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Zakāt (hadith of Ibn ʿUmar)",
    en: ["According to the hadith of Ibn ʿUmar in Ṣaḥīḥ al-Bukhārī, what is due on crops watered by rain or springs, compared with crops watered with effort and cost?", ["One tenth versus one twentieth", "One twentieth versus one tenth", "One fortieth in both cases", "One fifth versus one tenth"], "The hadith gives a tenth for land watered by the sky or springs and half a tenth for land irrigated by drawing water. The lower rate reflects the labour and cost of irrigation."],
    de: ["Was ist nach dem Hadith von Ibn ʿUmar in Ṣaḥīḥ al-Buḫārī auf Feldfrüchte fällig, die von Regen oder Quellen bewässert werden, verglichen mit mühsam und kostspielig bewässerten?", ["Ein Zehntel gegenüber einem Zwanzigstel", "Ein Zwanzigstel gegenüber einem Zehntel", "In beiden Fällen ein Vierzigstel", "Ein Fünftel gegenüber einem Zehntel"], "Der Hadith nennt ein Zehntel für vom Himmel oder von Quellen bewässertes Land und ein halbes Zehntel für Land, das durch Wasserschöpfen bewässert wird. Der niedrigere Satz berücksichtigt die Mühe und die Kosten der Bewässerung."],
    ar: ["بحسب حديث ابن عمر في صحيح البخاري، ما الواجب فيما سقته السماء والعيون مقارنةً بما سُقي بمؤونة؟", ["العشر مقابل نصف العشر", "نصف العشر مقابل العشر", "ربع العشر في الحالين", "الخمس مقابل العشر"], "في الحديث: فيما سقت السماء والعيون العشر، وفيما سُقي بالنضح نصف العشر؛ وخُفّف الواجب لما فيه من الكلفة والمؤونة."] },

  { id: "fqz-037", s: "fiqh", g: 2, d: 2, t: ["zakat-livestock", "nisab"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Zakāt (letter of Abū Bakr, hadith of Anas)", tr: ["ijma"],
    en: ["According to the letter of Abū Bakr in Ṣaḥīḥ al-Bukhārī, what is the niṣāb of sheep and goats and what is due on it?", ["Forty head, on which one sheep is due", "Thirty head, on which one sheep is due", "Twenty head, on which one sheep is due", "Fifty head, on which two sheep are due"], "The letter states that on grazing sheep from forty to one hundred and twenty one sheep is due. Thirty is the niṣāb of cattle, not of sheep."],
    de: ["Wie hoch ist nach dem Brief von Abū Bakr in Ṣaḥīḥ al-Buḫārī der Niṣāb bei Schafen und Ziegen und was ist darauf fällig?", ["Vierzig Tiere, darauf ein Schaf", "Dreißig Tiere, darauf ein Schaf", "Zwanzig Tiere, darauf ein Schaf", "Fünfzig Tiere, darauf zwei Schafe"], "Der Brief legt fest, dass auf weidende Schafe von vierzig bis hundertzwanzig ein Schaf fällig ist. Dreißig ist der Niṣāb der Rinder, nicht der Schafe."],
    ar: ["بحسب كتاب أبي بكر في صحيح البخاري، ما نصاب الغنم وما الواجب فيه؟", ["أربعون، وفيها شاة", "ثلاثون، وفيها شاة", "عشرون، وفيها شاة", "خمسون، وفيها شاتان"], "في كتاب الصدقة: في صدقة الغنم في سائمتها إذا كانت أربعين إلى عشرين ومئة شاة، أما الثلاثون فنصاب البقر لا الغنم."] },

  { id: "fqz-038", s: "fiqh", g: 2, d: 2, t: ["zakat-livestock", "nisab"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Zakāt (letter of Abū Bakr, hadith of Anas)", tr: ["ijma"],
    en: ["What is the niṣāb of camels, and what is due at that number?", ["Five camels, on which one sheep is due", "Five camels, on which one young she-camel is due", "Ten camels, on which one camel is due", "Twenty-five camels, on which one sheep is due"], "From five camels one sheep is due, and one more sheep for every further five up to twenty-four. At twenty-five the due becomes a camel, a bint makhāḍ."],
    de: ["Wie hoch ist der Niṣāb bei Kamelen und was ist bei dieser Zahl fällig?", ["Fünf Kamele, darauf ein Schaf", "Fünf Kamele, darauf eine junge Kamelstute", "Zehn Kamele, darauf ein Kamel", "Fünfundzwanzig Kamele, darauf ein Schaf"], "Ab fünf Kamelen ist ein Schaf fällig und für je weitere fünf ein weiteres Schaf bis vierundzwanzig. Ab fünfundzwanzig wird ein Kamel fällig, eine bint maḫāḍ."],
    ar: ["ما نصاب الإبل وما الواجب فيه؟", ["خمس من الإبل، وفيها شاة", "خمس من الإبل، وفيها بنت مخاض", "عشر من الإبل، وفيها بعير", "خمس وعشرون، وفيها شاة"], "في خمس من الإبل شاة، وفي كل خمس شاة إلى أربع وعشرين، فإذا بلغت خمسًا وعشرين ففيها بنت مخاض."] },

  { id: "fqz-039", s: "fiqh", g: 2, d: 3, t: ["zakat-livestock", "nisab"], src: "Abū Dāwūd and al-Tirmidhī, Kitāb al-Zakāt (hadith of Muʿādh); Ibn Qudāma, al-Mughnī, Bāb Ṣadaqat al-Baqar", tr: ["jumhur"],
    en: ["According to the hadith of Muʿādh, what is due on thirty head of cattle?", ["A one-year-old calf (tabīʿ or tabīʿa)", "A two-year-old cow (musinna)", "One sheep", "Nothing until they reach forty"], "Muʿādh was sent to Yemen with the instruction to take a tabīʿ or tabīʿa from every thirty cattle and a musinna from every forty. The musinna is therefore the due on forty, not thirty."],
    de: ["Was ist nach dem Hadith von Muʿāḏ auf dreißig Rinder fällig?", ["Ein einjähriges Kalb (tabīʿ oder tabīʿa)", "Eine zweijährige Kuh (musinna)", "Ein Schaf", "Nichts, bis sie vierzig erreichen"], "Muʿāḏ wurde mit der Anweisung in den Jemen gesandt, von je dreißig Rindern ein tabīʿ oder eine tabīʿa und von je vierzig eine musinna zu nehmen. Die musinna ist also bei vierzig fällig, nicht bei dreißig."],
    ar: ["بحسب حديث معاذ، ما الواجب في ثلاثين من البقر؟", ["تبيع أو تبيعة", "مسنّة", "شاة", "لا شيء حتى تبلغ أربعين"], "بعث النبي ﷺ معاذًا إلى اليمن وأمره أن يأخذ من كل ثلاثين بقرة تبيعًا أو تبيعة، ومن كل أربعين مسنّة، فالمسنّة في الأربعين لا في الثلاثين."] },

  { id: "fqz-040", s: "fiqh", g: 2, d: 2, t: ["zakat-crops", "hawl"], src: "Ibn Kathīr, Tafsīr, on 6:141; Ibn Qudāma, al-Mughnī, Bāb Zakāt al-Zurūʿ wa-l-Thimār", v: "6:141", tr: ["ijma"],
    en: ["The verse shown commands giving the due of produce on the day of its harvest. What follows for the zakāt of crops?", ["No full year (ḥawl) is required; it is due at harvest", "It is due only after a full lunar year", "It is due only at the end of Ramaḍān", "It is due only if the crop is sold"], "Jurists cite this verse to show that crops and fruits are not subject to the ḥawl: zakāt is due when they are harvested and ripe. The ḥawl applies to money, trade goods and livestock."],
    de: ["Die angezeigte Āya gebietet, das Recht der Früchte am Tag ihrer Ernte zu geben. Was folgt daraus für die Zakāt der Feldfrüchte?", ["Kein volles Jahr (Ḥaul) ist nötig; sie ist bei der Ernte fällig", "Sie ist erst nach einem vollen Mondjahr fällig", "Sie ist nur am Ende des Ramaḍān fällig", "Sie ist nur fällig, wenn die Ernte verkauft wird"], "Die Juristen führen diese Āya an, um zu zeigen, dass Feldfrüchte und Früchte nicht dem Ḥaul unterliegen: Die Zakāt wird mit Ernte und Reife fällig. Der Ḥaul gilt für Geld, Handelsware und Vieh."],
    ar: ["تأمر الآية المعروضة بإيتاء حق الثمر يوم حصاده، فما الذي يترتب على ذلك في زكاة الزروع؟", ["لا يُشترط الحول، بل تجب عند الحصاد", "لا تجب إلا بعد حول قمري", "لا تجب إلا في آخر رمضان", "لا تجب إلا إذا بيع المحصول"], "استدل الفقهاء بهذه الآية على أن الزروع والثمار لا يُشترط لها الحول، بل تجب الزكاة فيها عند الحصاد وبدوّ الصلاح، والحول شرط في النقدين والعروض والماشية."] },

  { id: "fqz-041", s: "fiqh", g: 2, d: 3, t: ["zakat-crops", "nisab", "school-differences"], src: "al-Bukhārī and Muslim, Kitāb al-Zakāt (hadith of Abū Saʿīd); Ibn Rushd, Bidāyat al-Mujtahid", tr: ["jumhur", "hanafi"],
    en: ["According to the majority, based on the hadith of Abū Saʿīd in al-Bukhārī and Muslim, what is the niṣāb of grain and dates?", ["Five awsuq", "Five ṣāʿs", "Forty awsuq", "Two hundred ṣāʿs"], "The hadith states that nothing is due on less than five awsuq; a wasq is sixty ṣāʿs, so the niṣāb is three hundred ṣāʿs. Abū Ḥanīfa held that the tithe is due on the land's produce whether little or much."],
    de: ["Wie hoch ist nach der Mehrheit, gestützt auf den Hadith von Abū Saʿīd bei al-Buḫārī und Muslim, der Niṣāb bei Getreide und Datteln?", ["Fünf Ausuq", "Fünf Ṣāʿ", "Vierzig Ausuq", "Zweihundert Ṣāʿ"], "Der Hadith besagt, dass auf weniger als fünf Ausuq nichts fällig ist; ein Wasq sind sechzig Ṣāʿ, der Niṣāb also dreihundert Ṣāʿ. Abū Ḥanīfa hielt den Zehnten auf den Ertrag des Bodens für fällig, ob wenig oder viel."],
    ar: ["ما نصاب الحبوب والتمر عند الجمهور بناءً على حديث أبي سعيد في الصحيحين؟", ["خمسة أوسق", "خمسة آصع", "أربعون وسقًا", "مئتا صاع"], "في الحديث: ليس فيما دون خمسة أوسق صدقة، والوسق ستون صاعًا فالنصاب ثلاثمئة صاع، وذهب أبو حنيفة إلى وجوب العشر في قليل ما أخرجته الأرض وكثيره."] },

  { id: "fqz-042", s: "fiqh", g: 2, d: 2, t: ["rikaz", "zakat-rates"], src: "al-Bukhārī and Muslim, Kitāb al-Zakāt (hadith of Abū Hurayra)", tr: ["ijma"],
    en: ["What is due on rikāz (treasure buried in pre-Islamic times) found by someone?", ["One fifth", "One tenth", "One fortieth", "One half"], "The Prophet ﷺ said in the hadith of Abū Hurayra in al-Bukhārī and Muslim that on rikāz the fifth is due. No ḥawl is required, since it comes to the finder without labour over time."],
    de: ["Was ist auf Rikāz (in vorislamischer Zeit vergrabene Schätze) fällig, wenn jemand ihn findet?", ["Ein Fünftel", "Ein Zehntel", "Ein Vierzigstel", "Die Hälfte"], "Der Prophet ﷺ sagte im Hadith von Abū Huraira bei al-Buḫārī und Muslim, dass auf Rikāz das Fünftel fällig ist. Ein Ḥaul ist nicht erforderlich."],
    ar: ["ما الواجب في الركاز (دفين الجاهلية) إذا وجده شخص؟", ["الخمس", "العشر", "ربع العشر", "النصف"], "قال النبي ﷺ في حديث أبي هريرة في الصحيحين: وفي الركاز الخمس، ولا يُشترط له حول."] },

  { id: "fqz-043", s: "fiqh", g: 2, d: 2, t: ["zakat-recipients"], src: "Ibn Qudāma, al-Mughnī, Bāb Ahl al-Zakāt; Ibn al-Mundhir, al-Ijmāʿ", tr: ["ijma"],
    en: ["To whom may a person NOT give his own zakāt, by agreement of the scholars?", ["His parents and children whom he is obliged to support", "A poor neighbour", "A debtor unable to pay", "A stranded traveller"], "One may not give zakāt to one's ascendants and descendants whose maintenance one owes, because the benefit would return to oneself. A poor neighbour, an insolvent debtor and a stranded traveller belong to the eight categories."],
    de: ["Wem darf jemand nach Übereinstimmung der Gelehrten seine eigene Zakāt NICHT geben?", ["Seinen Eltern und Kindern, für deren Unterhalt er aufkommen muss", "Einem armen Nachbarn", "Einem zahlungsunfähigen Schuldner", "Einem gestrandeten Reisenden"], "Man darf die Zakāt nicht den Vorfahren und Nachkommen geben, deren Unterhalt man schuldet, da der Nutzen zu einem selbst zurückkehren würde. Ein armer Nachbar, ein zahlungsunfähiger Schuldner und ein gestrandeter Reisender gehören zu den acht Gruppen."],
    ar: ["لمن لا يجوز للمسلم أن يدفع زكاته باتفاق العلماء؟", ["أصوله وفروعه الذين تلزمه نفقتهم", "جاره الفقير", "المدين العاجز عن السداد", "ابن السبيل المنقطع"], "لا يجوز دفع الزكاة إلى الأصول والفروع الذين تجب نفقتهم لأن نفعها يعود إليه، أما الجار الفقير والغارم وابن السبيل فمن الأصناف الثمانية."] },

  { id: "fqz-044", s: "fiqh", g: 2, d: 3, t: ["zakat-recipients"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Zakāt (hadith of ʿAbd al-Muṭṭalib ibn Rabīʿa); Ibn Qudāma, al-Mughnī", tr: ["jumhur"],
    en: ["Which group is excluded from receiving zakāt according to the hadith in Ṣaḥīḥ Muslim that ṣadaqa is not fitting for them?", ["The family of the Prophet ﷺ (Banū Hāshim)", "The Anṣār of Medina", "Converts to Islam", "Residents of Makka"], "The Prophet ﷺ said that ṣadaqa is not fitting for the family of Muḥammad, being the impurities of people's wealth. The majority therefore exclude Banū Hāshim from obligatory zakāt."],
    de: ["Welche Gruppe ist nach dem Hadith in Ṣaḥīḥ Muslim, dass die Ṣadaqa ihnen nicht zusteht, vom Empfang der Zakāt ausgeschlossen?", ["Die Familie des Propheten ﷺ (Banū Hāšim)", "Die Anṣār von Medina", "Konvertiten zum Islam", "Die Bewohner Mekkas"], "Der Prophet ﷺ sagte, die Ṣadaqa stehe der Familie Muḥammads nicht zu, da sie die Unreinheiten des Vermögens der Menschen sei. Die Mehrheit schließt daher die Banū Hāšim von der Pflicht-Zakāt aus."],
    ar: ["أيّ فئة مُنعت من أخذ الزكاة بحديث صحيح مسلم أن الصدقة لا تنبغي لهم؟", ["آل النبي ﷺ من بني هاشم", "الأنصار من أهل المدينة", "حديثو العهد بالإسلام", "أهل مكة"], "قال النبي ﷺ: إن الصدقة لا تنبغي لآل محمد، إنما هي أوساخ الناس، فذهب الجمهور إلى منع بني هاشم من الزكاة المفروضة."] },

  { id: "fqz-045", s: "fiqh", g: 3, d: 3, t: ["jewellery", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Zakāt; Ibn Qudāma, al-Mughnī; Ibn Rushd, Bidāyat al-Mujtahid", tr: ["comparative", "hanafi", "jumhur"],
    en: ["Which statement correctly describes the disagreement about zakāt on gold and silver jewellery worn by a woman in a permissible way?", ["The Ḥanafīs require zakāt on it; the Mālikīs, Shāfiʿīs and Ḥanbalīs do not", "The Mālikīs require zakāt on it; the other three schools do not", "All four schools require zakāt on it", "No school requires zakāt on it"], "The Ḥanafīs treat gold and silver as zakatable in themselves, whatever their use. The majority liken jewellery in permitted use to personal belongings such as clothes, which are not zakatable; jewellery hoarded or used in a forbidden way remains subject to zakāt."],
    de: ["Welche Aussage beschreibt den Meinungsunterschied über die Zakāt auf Gold- und Silberschmuck, den eine Frau in erlaubter Weise trägt, richtig?", ["Die Ḥanafiten verlangen darauf Zakāt; Malikiten, Šāfiʿiten und Ḥanbaliten nicht", "Die Malikiten verlangen darauf Zakāt; die anderen drei Schulen nicht", "Alle vier Schulen verlangen darauf Zakāt", "Keine Schule verlangt darauf Zakāt"], "Die Ḥanafiten betrachten Gold und Silber an sich als zakātpflichtig, gleich wie sie verwendet werden. Die Mehrheit vergleicht Schmuck im erlaubten Gebrauch mit persönlichen Gegenständen wie Kleidung, die nicht zakātpflichtig sind; gehorteter oder verbotswidrig genutzter Schmuck bleibt zakātpflichtig."],
    ar: ["أيّ العبارات تصف الخلاف في زكاة حُليّ الذهب والفضة الذي تلبسه المرأة لبسًا مباحًا وصفًا صحيحًا؟", ["يوجبها الحنفية، ولا يوجبها المالكية والشافعية والحنابلة", "يوجبها المالكية، ولا يوجبها الثلاثة", "يوجبها الأربعة", "لا يوجبها أحد منهم"], "يرى الحنفية أن الذهب والفضة مال زكوي بأصله أيًّا كان استعماله، وألحق الجمهور الحليّ المباح بالثياب والمتاع المستعمل فلا زكاة فيه، أما المكنوز أو المحرّم فتجب فيه الزكاة."] },

  { id: "fqz-046", s: "fiqh", g: 3, d: 3, t: ["zakat-recipients", "school-differences"], src: "Ibn Qudāma, al-Mughnī, Bāb Ahl al-Zakāt; al-Marghīnānī, al-Hidāya, Bāb Man Yajūz Dafʿ al-Ṣadaqa Ilayh", v: "9:60", tr: ["comparative", "hanafi", "maliki", "shafii", "hanbali"],
    en: ["Which statement correctly describes the disagreement about whether the faqīr or the miskīn named in the verse shown is in greater need?", ["Shāfiʿīs and Ḥanbalīs: the faqīr is worse off; Ḥanafīs and Mālikīs: the miskīn is worse off", "Ḥanafīs and Mālikīs: the faqīr is worse off; Shāfiʿīs and Ḥanbalīs: the miskīn is worse off", "All four schools: the two words mean exactly the same", "All four schools: the miskīn has wealth above the niṣāb"], "The Shāfiʿīs and Ḥanbalīs note that the verse begins with the faqīr, and that elsewhere the Quran calls people miskīn who own a ship. The Ḥanafīs and Mālikīs define the miskīn as the one who owns nothing at all. Both categories receive zakāt in every school."],
    de: ["Welche Aussage beschreibt den Meinungsunterschied darüber, ob der in der angezeigten Āya genannte Faqīr oder der Miskīn bedürftiger ist, richtig?", ["Šāfiʿiten und Ḥanbaliten: Der Faqīr ist schlechter gestellt; Ḥanafiten und Malikiten: der Miskīn", "Ḥanafiten und Malikiten: Der Faqīr ist schlechter gestellt; Šāfiʿiten und Ḥanbaliten: der Miskīn", "Alle vier Schulen: Beide Wörter bedeuten genau dasselbe", "Alle vier Schulen: Der Miskīn hat Vermögen über dem Niṣāb"], "Šāfiʿiten und Ḥanbaliten verweisen darauf, dass die Āya mit dem Faqīr beginnt und der Koran an anderer Stelle Besitzer eines Schiffes als Masākīn bezeichnet. Ḥanafiten und Malikiten definieren den Miskīn als den, der gar nichts besitzt. Beide Gruppen erhalten in jeder Schule Zakāt."],
    ar: ["أيّ العبارات تصف الخلاف في أيّهما أشدّ حاجة: الفقير أم المسكين المذكوران في الآية المعروضة؟", ["الشافعية والحنابلة: الفقير أشدّ حاجة، والحنفية والمالكية: المسكين أشدّ حاجة", "الحنفية والمالكية: الفقير أشدّ حاجة، والشافعية والحنابلة: المسكين أشدّ حاجة", "الأربعة: اللفظان بمعنى واحد تمامًا", "الأربعة: المسكين يملك فوق النصاب"], "احتج الشافعية والحنابلة بالبدء بالفقراء في الآية وبتسمية أصحاب السفينة مساكين في موضع آخر، وعرّف الحنفية والمالكية المسكين بأنه من لا يملك شيئًا، وكلاهما من أهل الزكاة في كل المذاهب."] },

  { id: "fqz-047", s: "fiqh", g: 3, d: 4, t: ["zakat-recipients", "school-differences"], src: "al-Nawawī, Minhāj al-Ṭālibīn, Kitāb Qasm al-Ṣadaqāt; Ibn Rushd, Bidāyat al-Mujtahid", v: "9:60", tr: ["shafii", "comparative"],
    en: ["Which school holds that zakāt must be divided among all the categories of the verse shown that are present, rather than given to one category?", ["The Shāfiʿī school", "The Ḥanafī school", "The Mālikī school", "The Ḥanbalī school (its relied view)"], "The Shāfiʿīs read the verse as allocating zakāt to the eight categories jointly, so it must be spread over all those present, at least three persons from each. The Ḥanafīs, Mālikīs and the relied Ḥanbalī view hold that the verse names who is eligible and allow giving all of it to one category."],
    de: ["Welche Schule hält, dass die Zakāt auf alle vorhandenen Gruppen der angezeigten Āya verteilt werden muss, statt einer einzigen Gruppe gegeben zu werden?", ["Die šāfiʿitische Schule", "Die ḥanafitische Schule", "Die malikitische Schule", "Die ḥanbalitische Schule (maßgebliche Ansicht)"], "Die Šāfiʿiten verstehen die Āya so, dass die Zakāt den acht Gruppen gemeinsam zugewiesen ist; sie muss daher auf alle vorhandenen verteilt werden, mindestens an drei Personen je Gruppe. Ḥanafiten, Malikiten und die maßgebliche ḥanbalitische Ansicht sehen in der Āya die Benennung der Berechtigten und erlauben, alles einer Gruppe zu geben."],
    ar: ["أيّ مذهب يوجب تعميم الأصناف الموجودة من الآية المعروضة بالزكاة بدل دفعها إلى صنف واحد؟", ["المذهب الشافعي", "المذهب الحنفي", "المذهب المالكي", "المذهب الحنبلي في المعتمد"], "جعل الشافعية اللام في الآية للتمليك والواو للتشريك، فأوجبوا استيعاب الأصناف الموجودة وأقلّه ثلاثة من كل صنف، وحملها الحنفية والمالكية والمعتمد عند الحنابلة على بيان المصارف فأجازوا دفعها إلى صنف واحد."] },

  { id: "fqz-048", s: "fiqh", g: 3, d: 3, t: ["zakat-conditions", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Zakāt; Ibn Qudāma, al-Mughnī", tr: ["hanafi", "jumhur", "comparative"],
    en: ["Which statement correctly describes the disagreement about zakāt on the wealth of a child or an insane person?", ["The majority make it due, paid by the guardian; the Ḥanafīs do not, except the tithe on crops and Zakāt al-Fiṭr", "The Ḥanafīs make it due on all wealth; the majority exempt it entirely", "All four schools make it due only after the child reaches puberty, for all past years", "All four schools exempt all their wealth, including crops"], "The majority view zakāt as a right attached to the wealth itself, so the guardian pays it. The Ḥanafīs view it as an act of worship requiring legal capacity, so they exempt the money and livestock of a child, while still requiring the tithe on crops and Zakāt al-Fiṭr."],
    de: ["Welche Aussage beschreibt den Meinungsunterschied über die Zakāt auf das Vermögen eines Kindes oder eines Geistesgestörten richtig?", ["Die Mehrheit hält sie für fällig, gezahlt vom Vormund; die Ḥanafiten nicht, außer dem Zehnten auf Feldfrüchte und der Zakāt al-Fiṭr", "Die Ḥanafiten halten sie auf alles Vermögen für fällig; die Mehrheit befreit es völlig", "Alle vier Schulen halten sie erst nach der Pubertät für alle vergangenen Jahre für fällig", "Alle vier Schulen befreien ihr gesamtes Vermögen einschließlich der Feldfrüchte"], "Die Mehrheit sieht die Zakāt als ein am Vermögen selbst haftendes Recht, sodass der Vormund sie entrichtet. Die Ḥanafiten sehen sie als Gottesdienst, der Rechtsfähigkeit voraussetzt, und befreien daher Geld und Vieh eines Kindes, verlangen aber den Zehnten auf Feldfrüchte und die Zakāt al-Fiṭr."],
    ar: ["أيّ العبارات تصف الخلاف في زكاة مال الصبي والمجنون وصفًا صحيحًا؟", ["يوجبها الجمهور ويخرجها الولي، ولا يوجبها الحنفية إلا العشر وصدقة الفطر", "يوجبها الحنفية في كل المال، ويسقطها الجمهور كليًّا", "يوجبها الأربعة بعد البلوغ عن السنين الماضية فقط", "يسقطها الأربعة في كل مالهما حتى الزروع"], "يرى الجمهور الزكاة حقًّا متعلقًا بالمال فيخرجها الولي، ويراها الحنفية عبادة محضة تفتقر إلى التكليف فأسقطوها عن نقود الصبي وماشيته، وأوجبوا العشر في زرعه وصدقة الفطر عنه."] },

  { id: "fqz-049", s: "fiqh", g: 3, d: 4, t: ["zakat-livestock", "school-differences"], src: "Khalīl, al-Mukhtaṣar, Bāb al-Zakāt; Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Zakāt", tr: ["maliki", "comparative"],
    en: ["Which school does NOT make free grazing (sawm) a condition for zakāt on livestock, and so requires it also on fodder-fed and working animals?", ["The Mālikī school", "The Ḥanafī school", "The Shāfiʿī school", "The Ḥanbalī school"], "Khalīl states that zakāt is due on livestock even if fed with fodder or used for work, following the general texts on camels, cattle and sheep. The other three schools restrict it to animals that graze freely for most of the year, because the hadith qualifies sheep as grazing (sāʾima)."],
    de: ["Welche Schule macht das freie Weiden (saum) NICHT zur Bedingung der Zakāt auf Vieh und verlangt sie daher auch bei stallgefütterten und Arbeitstieren?", ["Die malikitische Schule", "Die ḥanafitische Schule", "Die šāfiʿitische Schule", "Die ḥanbalitische Schule"], "Ḫalīl stellt fest, dass die Zakāt auf Vieh auch dann fällig ist, wenn es gefüttert oder zur Arbeit eingesetzt wird, gemäß den allgemeinen Texten über Kamele, Rinder und Schafe. Die anderen drei Schulen beschränken sie auf Tiere, die den größten Teil des Jahres frei weiden, da der Hadith die Schafe als weidend (sāʾima) beschreibt."],
    ar: ["أيّ مذهب لا يشترط السَّوم في زكاة الماشية فيوجبها في المعلوفة والعاملة أيضًا؟", ["المذهب المالكي", "المذهب الحنفي", "المذهب الشافعي", "المذهب الحنبلي"], "نصّ خليل على وجوب الزكاة في النعم وإن كانت معلوفة أو عاملة أخذًا بعموم النصوص، وقصرها الثلاثة على السائمة أكثر الحول لتقييد الحديث الغنم بالسائمة."] },

  { id: "fqz-050", s: "fiqh", g: 3, d: 3, t: ["nisab", "zakat-money"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Zakāt, on the niṣāb of gold; modern conversions of the mithqāl", tr: ["jumhur"],
    en: ["Modern writers commonly convert the gold niṣāb of twenty mithqāls into roughly how many grams of gold?", ["About 85 grams", "About 595 grams", "About 200 grams", "About 20 grams"], "Taking a mithqāl as roughly 4.25 grams gives about 85 grams; conversions differ slightly with the estimate of the mithqāl. About 595 grams is the commonly cited conversion for the silver niṣāb of two hundred dirhams."],
    de: ["In ungefähr wie viele Gramm Gold rechnen heutige Autoren den Gold-Niṣāb von zwanzig Miṯqāl gewöhnlich um?", ["Etwa 85 Gramm", "Etwa 595 Gramm", "Etwa 200 Gramm", "Etwa 20 Gramm"], "Setzt man einen Miṯqāl mit etwa 4,25 Gramm an, ergeben sich rund 85 Gramm; je nach Schätzung des Miṯqāl weichen die Umrechnungen leicht ab. Etwa 595 Gramm ist die übliche Umrechnung für den Silber-Niṣāb von zweihundert Dirham."],
    ar: ["كم غرامًا من الذهب يعادل تقريبًا نصاب الذهب البالغ عشرين مثقالًا في التقديرات المعاصرة الشائعة؟", ["نحو 85 غرامًا", "نحو 595 غرامًا", "نحو 200 غرام", "نحو 20 غرامًا"], "إذا قُدّر المثقال بنحو 4.25 غرامات كان النصاب قرابة 85 غرامًا، وتختلف التقديرات يسيرًا باختلاف تقدير المثقال، أما نحو 595 غرامًا فهو التقدير الشائع لنصاب الفضة مئتي درهم."] },

  { id: "fqz-051", s: "fiqh", g: 3, d: 4, t: ["zakat-livestock", "zakat-rates"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Zakāt (letter of Abū Bakr, hadith of Anas)", tr: ["jumhur"],
    en: ["A herd of 130 freely grazing sheep completes the year. How many sheep are due?", ["Two", "One", "Three", "Four"], "According to the letter of Abū Bakr, one sheep is due from forty to one hundred and twenty, two from one hundred and twenty-one to two hundred, and three from two hundred and one to three hundred. 130 therefore falls into the bracket of two."],
    de: ["Eine Herde von 130 frei weidenden Schafen vollendet das Jahr. Wie viele Schafe sind fällig?", ["Zwei", "Eines", "Drei", "Vier"], "Nach dem Brief von Abū Bakr ist von vierzig bis hundertzwanzig ein Schaf fällig, von hunderteinundzwanzig bis zweihundert zwei und von zweihundertundeins bis dreihundert drei. 130 fällt daher in die Stufe von zwei."],
    ar: ["قطيع من مئة وثلاثين شاة سائمة حال عليه الحول، فكم شاة تجب فيه؟", ["شاتان", "شاة واحدة", "ثلاث شياه", "أربع شياه"], "في كتاب أبي بكر: من أربعين إلى عشرين ومئة شاة، فإذا زادت على عشرين ومئة إلى مئتين فشاتان، فإذا زادت على مئتين إلى ثلاثمئة فثلاث، فالمئة والثلاثون فيها شاتان."] },

  { id: "fqz-052", s: "fiqh", g: 4, d: 4, t: ["zakat-recipients", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Bāb Man Yajūz Dafʿ al-Ṣadaqa Ilayh; Ibn Qudāma, al-Mughnī", v: "9:60", w: 7, tr: ["hanafi", "comparative"],
    en: ["The highlighted word begins the category of those whose hearts are to be reconciled. Which school holds that this share has lapsed?", ["The Ḥanafī school", "The Ḥanbalī school", "The Shāfiʿī school", "The Mālikī school according to Khalīl"], "The Ḥanafīs hold that the share lapsed because Islam became strong, citing ʿUmar's refusal to continue the payments in the time of Abū Bakr without objection from the Companions. The Ḥanbalīs keep the share when there is need, and Khalīl states that its ruling remains."],
    de: ["Das hervorgehobene Wort leitet die Gruppe derer ein, deren Herzen gewonnen werden sollen. Welche Schule hält diesen Anteil für entfallen?", ["Die ḥanafitische Schule", "Die ḥanbalitische Schule", "Die šāfiʿitische Schule", "Die malikitische Schule nach Ḫalīl"], "Die Ḥanafiten halten den Anteil für entfallen, weil der Islam stark geworden sei, und verweisen darauf, dass ʿUmar zur Zeit Abū Bakrs die Zahlungen ohne Widerspruch der Gefährten verweigerte. Die Ḥanbaliten halten den Anteil bei Bedarf aufrecht, und Ḫalīl stellt fest, dass sein Urteil fortbesteht."],
    ar: ["الكلمة المظللة يبدأ بها صنف المؤلفة قلوبهم، فأيّ مذهب يرى أن سهمهم قد سقط؟", ["المذهب الحنفي", "المذهب الحنبلي", "المذهب الشافعي", "المذهب المالكي عند خليل"], "يرى الحنفية سقوط سهم المؤلفة قلوبهم لإعزاز الله الإسلام، واستدلوا بمنع عمر لهم في عهد أبي بكر دون نكير من الصحابة، وأبقاه الحنابلة عند الحاجة، ونصّ خليل على بقاء حكمه."] },

  { id: "fqz-053", s: "fiqh", g: 4, d: 5, t: ["zakat-crops", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Bāb Zakāt al-Zurūʿ wa-l-Thimār", tr: ["hanafi", "comparative"],
    en: ["On the tithe of agricultural produce, how did Abū Ḥanīfa differ from his two companions Abū Yūsuf and Muḥammad?", ["He required it on little and much of almost all produce; they required a niṣāb of five awsuq and produce that keeps", "He required a niṣāb of five awsuq; they required it on little and much", "He limited it to wheat and barley; they extended it to all produce", "He required a full year after harvest; they required it at harvest"], "Al-Hidāya reports that Abū Ḥanīfa required the tithe on whatever the land produces, little or much, except things like firewood, reeds and grass, while Abū Yūsuf and Muḥammad required five awsuq and limited it to produce that lasts a year, in line with the hadith of Abū Saʿīd."],
    de: ["Worin unterschied sich Abū Ḥanīfa beim Zehnten auf landwirtschaftliche Erzeugnisse von seinen beiden Schülern Abū Yūsuf und Muḥammad?", ["Er verlangte ihn auf wenig und viel fast aller Erträge; sie verlangten einen Niṣāb von fünf Ausuq und haltbare Erträge", "Er verlangte einen Niṣāb von fünf Ausuq; sie verlangten ihn auf wenig und viel", "Er beschränkte ihn auf Weizen und Gerste; sie dehnten ihn auf alle Erträge aus", "Er verlangte ein volles Jahr nach der Ernte; sie verlangten ihn bei der Ernte"], "Al-Hidāya berichtet, dass Abū Ḥanīfa den Zehnten auf alles verlangte, was der Boden hervorbringt, ob wenig oder viel, außer Dingen wie Brennholz, Schilf und Gras, während Abū Yūsuf und Muḥammad fünf Ausuq verlangten und ihn auf ein Jahr haltbare Erträge beschränkten, gemäß dem Hadith von Abū Saʿīd."],
    ar: ["كيف خالف أبو حنيفة صاحبيه أبا يوسف ومحمدًا في عشر ما تخرجه الأرض؟", ["أوجبه في قليل كل ما تخرجه الأرض وكثيره، وشرطا خمسة أوسق وما يبقى", "شرط خمسة أوسق، وأوجباه في القليل والكثير", "قصره على البر والشعير، وعمّماه في كل خارج", "أوجبه بعد حول من الحصاد، وأوجباه عند الحصاد"], "في الهداية: أوجب أبو حنيفة العشر في قليل ما أخرجته الأرض وكثيره إلا الحطب والقصب والحشيش، وقال الصاحبان: لا يجب إلا فيما له ثمرة باقية إذا بلغ خمسة أوسق، عملًا بحديث أبي سعيد."] },

  { id: "fqz-054", s: "fiqh", g: 4, d: 4, t: ["zakat-crops", "school-differences"], src: "al-Nawawī, Minhāj al-Ṭālibīn, Bāb Zakāt al-Nabāt", tr: ["shafii", "comparative"],
    en: ["According to the Shāfiʿī school as stated in Minhāj al-Ṭālibīn, which produce is subject to the tithe?", ["Staple foods eaten by choice, such as wheat, barley, rice and lentils, plus dates and grapes", "Everything the land produces except firewood, grass and reeds", "Only wheat, barley, dates and raisins, as named in some reports", "All fruits and vegetables that are sold at market"], "Al-Nawawī restricts the zakāt of plants to staples (qūt) eaten in normal circumstances, and among fruits to fresh dates and grapes. The second option is Abū Ḥanīfa's view, and the third is a view reported from some early authorities."],
    de: ["Welche Erträge unterliegen nach der šāfiʿitischen Schule, wie in Minhāǧ aṭ-Ṭālibīn dargelegt, dem Zehnten?", ["Grundnahrungsmittel des freien Verzehrs wie Weizen, Gerste, Reis und Linsen sowie Datteln und Trauben", "Alles, was der Boden hervorbringt, außer Brennholz, Gras und Schilf", "Nur Weizen, Gerste, Datteln und Rosinen, wie in einigen Berichten genannt", "Alle Früchte und Gemüse, die auf dem Markt verkauft werden"], "An-Nawawī beschränkt die Zakāt der Pflanzen auf Grundnahrungsmittel (qūt), die unter normalen Umständen gegessen werden, und bei den Früchten auf frische Datteln und Trauben. Die zweite Option ist die Ansicht Abū Ḥanīfas, die dritte eine von einigen Frühen überlieferte Ansicht."],
    ar: ["ما الذي تجب فيه زكاة النبات عند الشافعية كما في منهاج الطالبين؟", ["القوت اختيارًا كالحنطة والشعير والأرز والعدس، ومن الثمار الرطب والعنب", "كل ما تخرجه الأرض إلا الحطب والحشيش والقصب", "الحنطة والشعير والتمر والزبيب فقط كما في بعض الآثار", "كل الفواكه والخضروات التي تُباع في السوق"], "قصر النووي زكاة النبات على القوت في حال الاختيار، ومن الثمار على الرطب والعنب، والخيار الثاني قول أبي حنيفة، والثالث قول مروي عن بعض السلف."] },

  { id: "fqz-055", s: "fiqh", g: 2, d: 3, t: ["zakat-conditions"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Zakāt; Ibn Rushd, Bidāyat al-Mujtahid, on the conditions of zakāt", tr: ["jumhur"],
    en: ["Which of the following is a condition for zakāt to be due on money according to the jurists?", ["Complete ownership of a niṣāb for a full year", "That the owner has performed the ḥajj", "That the money is held in a bank account", "That the owner has no living parents"], "The conditions commonly listed are Islam, freedom, complete ownership (milk tāmm) of a niṣāb and the passing of a ḥawl on money, livestock and trade goods. The other options have no basis in the law of zakāt."],
    de: ["Welche der folgenden ist nach den Juristen eine Bedingung dafür, dass auf Geld Zakāt fällig wird?", ["Vollständiges Eigentum an einem Niṣāb über ein volles Jahr", "Dass der Eigentümer den Ḥaǧǧ verrichtet hat", "Dass das Geld auf einem Bankkonto liegt", "Dass der Eigentümer keine lebenden Eltern hat"], "Die üblicherweise genannten Bedingungen sind Islam, Freiheit, vollständiges Eigentum (milk tāmm) an einem Niṣāb und das Verstreichen eines Ḥaul bei Geld, Vieh und Handelsware. Die übrigen Optionen haben im Zakāt-Recht keine Grundlage."],
    ar: ["أيّ مما يلي شرط لوجوب الزكاة في النقود عند الفقهاء؟", ["الملك التام للنصاب مع حولان الحول", "أن يكون المالك قد حجّ", "أن يكون المال في حساب مصرفي", "ألا يكون للمالك والدان أحياء"], "شروط وجوب الزكاة المذكورة عند الفقهاء: الإسلام، والحرية، وملك النصاب ملكًا تامًّا، وحولان الحول في النقدين والماشية والعروض، والخيارات الأخرى لا أصل لها."] },

  // ───────────── Ḥajj and ʿUmra ─────────────
  { id: "fqz-056", s: "fiqh", g: 1, d: 1, t: ["hajj-basics", "hajj-conditions"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ḥajj (hadith of Abū Hurayra); Ibn Qudāma, al-Mughnī, Kitāb al-Ḥajj", v: "3:97", tr: ["ijma"],
    en: ["Based on the verse shown and the Sunna, how often is ḥajj obligatory?", ["Once in a lifetime, for whoever is able", "Every year, for every adult Muslim", "Once every five years, for whoever is able", "Once in a lifetime, for everyone whether able or not"], "The verse makes ḥajj a duty on whoever is able to find a way to it. When asked whether it is every year, the Prophet ﷺ indicated that it is not (hadith of Abū Hurayra in Ṣaḥīḥ Muslim); by consensus it is obligatory once in a lifetime."],
    de: ["Wie oft ist der Ḥaǧǧ nach der angezeigten Āya und der Sunna verpflichtend?", ["Einmal im Leben, für den, der dazu fähig ist", "Jedes Jahr, für jeden erwachsenen Muslim", "Alle fünf Jahre, für den, der dazu fähig ist", "Einmal im Leben, für jeden, ob fähig oder nicht"], "Die Āya macht den Ḥaǧǧ zur Pflicht für den, der einen Weg dorthin findet. Auf die Frage, ob er jedes Jahr gelte, verneinte der Prophet ﷺ dies sinngemäß (Hadith von Abū Huraira in Ṣaḥīḥ Muslim); nach Konsens ist er einmal im Leben verpflichtend."],
    ar: ["كم مرة يجب الحج بناءً على الآية المعروضة والسنة؟", ["مرة في العمر على المستطيع", "كل عام على كل مسلم بالغ", "كل خمس سنوات على المستطيع", "مرة في العمر على كل أحد مستطيعًا أو لا"], "أوجبت الآية الحج على من استطاع إليه سبيلًا، ولما سُئل النبي ﷺ أفي كل عام؟ بيّن أنه لا يجب كل عام كما في حديث أبي هريرة في صحيح مسلم، وأجمع العلماء على أنه يجب مرة في العمر."] },

  { id: "fqz-057", s: "fiqh", g: 1, d: 1, t: ["arafa", "hajj-basics"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ḥajj, on the standing at ʿArafa", tr: ["ijma"],
    en: ["On which day do the pilgrims stand at ʿArafa?", ["The 9th of Dhū al-Ḥijja", "The 8th of Dhū al-Ḥijja", "The 10th of Dhū al-Ḥijja", "The 1st of Dhū al-Ḥijja"], "The Day of ʿArafa is the 9th of Dhū al-Ḥijja. The 8th is the Day of Tarwiya, when pilgrims go to Minā, and the 10th is the Day of Sacrifice."],
    de: ["An welchem Tag stehen die Pilger in ʿArafa?", ["Am 9. Ḏū l-Ḥiǧǧa", "Am 8. Ḏū l-Ḥiǧǧa", "Am 10. Ḏū l-Ḥiǧǧa", "Am 1. Ḏū l-Ḥiǧǧa"], "Der Tag von ʿArafa ist der 9. Ḏū l-Ḥiǧǧa. Der 8. ist der Tag der Tarwiya, an dem die Pilger nach Minā gehen, und der 10. ist der Opfertag."],
    ar: ["في أيّ يوم يقف الحجاج بعرفة؟", ["التاسع من ذي الحجة", "الثامن من ذي الحجة", "العاشر من ذي الحجة", "الأول من ذي الحجة"], "يوم عرفة هو التاسع من ذي الحجة، أما الثامن فيوم التروية يخرج فيه الحجاج إلى منى، والعاشر يوم النحر."] },

  { id: "fqz-058", s: "fiqh", g: 1, d: 1, t: ["tawaf"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ḥajj (hadith of Jābir); Ibn Qudāma, al-Mughnī", tr: ["ijma"],
    en: ["How is ṭawāf around the Kaʿba performed?", ["Seven circuits, starting at the Black Stone, with the Kaʿba on one's left", "Seven circuits, starting at the Yemeni corner, with the Kaʿba on one's right", "Three circuits, starting at the door of the Kaʿba", "Five circuits, starting at the Station of Ibrāhīm"], "Ṭawāf consists of seven circuits that begin and end at the Black Stone, moving with the Kaʿba on one's left, as in the description of the Prophet's ḥajj by Jābir in Ṣaḥīḥ Muslim."],
    de: ["Wie wird der Ṭawāf um die Kaʿba verrichtet?", ["Sieben Umrundungen, beginnend am Schwarzen Stein, die Kaʿba zur Linken", "Sieben Umrundungen, beginnend an der jemenitischen Ecke, die Kaʿba zur Rechten", "Drei Umrundungen, beginnend an der Tür der Kaʿba", "Fünf Umrundungen, beginnend an der Stätte Ibrāhīms"], "Der Ṭawāf besteht aus sieben Umrundungen, die am Schwarzen Stein beginnen und enden, wobei die Kaʿba zur Linken ist, wie es Ǧābir in seiner Beschreibung des Ḥaǧǧ des Propheten in Ṣaḥīḥ Muslim überliefert."],
    ar: ["كيف يكون الطواف بالكعبة؟", ["سبعة أشواط تبدأ من الحجر الأسود والكعبة عن يسار الطائف", "سبعة أشواط تبدأ من الركن اليماني والكعبة عن يمينه", "ثلاثة أشواط تبدأ من باب الكعبة", "خمسة أشواط تبدأ من مقام إبراهيم"], "الطواف سبعة أشواط يبتدئها من الحجر الأسود وينتهي إليه جاعلًا البيت عن يساره، كما في صفة حجة النبي ﷺ من حديث جابر في صحيح مسلم."] },

  { id: "fqz-059", s: "fiqh", g: 1, d: 1, t: ["say"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ḥajj (hadith of Jābir); Ibn Kathīr, Tafsīr, on 2:158", v: "2:158", w: 2, tr: ["ijma"],
    en: ["The highlighted word names a hill of the saʿy. What is its role?", ["The saʿy begins at it", "The saʿy ends at it after the seventh lap", "The ṭawāf begins at it", "Pebbles are thrown at it"], "In Jābir's hadith the Prophet ﷺ approached al-Ṣafā and said he would begin with what Allah began with, then started the saʿy from it. Each passage between al-Ṣafā and al-Marwa counts as one lap, so the seventh lap ends at al-Marwa."],
    de: ["Das hervorgehobene Wort nennt einen Hügel des Saʿy. Welche Rolle hat er?", ["Der Saʿy beginnt an ihm", "Der Saʿy endet an ihm nach der siebten Strecke", "Der Ṭawāf beginnt an ihm", "Auf ihn werden Steinchen geworfen"], "Im Hadith von Ǧābir näherte sich der Prophet ﷺ aṣ-Ṣafā und sagte, er beginne mit dem, womit Allah begonnen hat, und begann dort den Saʿy. Jede Strecke zwischen aṣ-Ṣafā und al-Marwa zählt als eine, sodass die siebte bei al-Marwa endet."],
    ar: ["الكلمة المظللة اسم جبل من جبلي السعي، فما شأنه؟", ["يبدأ منه السعي", "ينتهي إليه السعي بعد الشوط السابع", "يبدأ منه الطواف", "تُرمى عليه الحصى"], "في حديث جابر لما دنا النبي ﷺ من الصفا قال: أبدأ بما بدأ الله به، فبدأ بالصفا، والذهاب من الصفا إلى المروة شوط فينتهي السابع بالمروة."] },

  { id: "fqz-060", s: "fiqh", g: 1, d: 2, t: ["miqat"], src: "al-Bukhārī and Muslim, Kitāb al-Ḥajj (hadith of Ibn ʿAbbās on the mawāqīt)", tr: ["ijma"],
    en: ["Which mīqāt did the Prophet ﷺ appoint for the people of Medina?", ["Dhū al-Ḥulayfa", "al-Juḥfa", "Qarn al-Manāzil", "Yalamlam"], "In the hadith of Ibn ʿAbbās the Prophet ﷺ appointed Dhū al-Ḥulayfa for Medina, al-Juḥfa for al-Shām, Qarn al-Manāzil for Najd and Yalamlam for Yemen."],
    de: ["Welchen Mīqāt bestimmte der Prophet ﷺ für die Leute von Medina?", ["Ḏū l-Ḥulaifa", "al-Ǧuḥfa", "Qarn al-Manāzil", "Yalamlam"], "Im Hadith von Ibn ʿAbbās bestimmte der Prophet ﷺ Ḏū l-Ḥulaifa für Medina, al-Ǧuḥfa für aš-Šām, Qarn al-Manāzil für Naǧd und Yalamlam für den Jemen."],
    ar: ["ما الميقات الذي وقّته النبي ﷺ لأهل المدينة؟", ["ذو الحليفة", "الجحفة", "قرن المنازل", "يلملم"], "في حديث ابن عباس وقّت النبي ﷺ لأهل المدينة ذا الحليفة، ولأهل الشام الجحفة، ولأهل نجد قرن المنازل، ولأهل اليمن يلملم."] },

  { id: "fqz-061", s: "fiqh", g: 1, d: 2, t: ["ramy", "mina"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ḥajj (hadith of Jābir); Ibn Qudāma, al-Mughnī", tr: ["ijma"],
    en: ["On the Day of Sacrifice (10th Dhū al-Ḥijja), at which pillar do the pilgrims throw pebbles?", ["Only Jamrat al-ʿAqaba, with seven pebbles", "All three jamarāt, seven pebbles each", "Only the small jamra, with seven pebbles", "Only Jamrat al-ʿAqaba, with three pebbles"], "On the 10th the Prophet ﷺ threw only at Jamrat al-ʿAqaba, seven pebbles, saying takbīr with each. All three jamarāt are stoned on the days of tashrīq that follow."],
    de: ["Auf welchen Pfeiler werfen die Pilger am Opfertag (10. Ḏū l-Ḥiǧǧa) Steinchen?", ["Nur auf die Ǧamrat al-ʿAqaba, mit sieben Steinchen", "Auf alle drei Ǧamarāt, je sieben Steinchen", "Nur auf die kleine Ǧamra, mit sieben Steinchen", "Nur auf die Ǧamrat al-ʿAqaba, mit drei Steinchen"], "Am 10. warf der Prophet ﷺ nur auf die Ǧamrat al-ʿAqaba, sieben Steinchen, mit einem Takbīr bei jedem. Alle drei Ǧamarāt werden an den folgenden Tašrīq-Tagen beworfen."],
    ar: ["ما الجمرة التي يرميها الحجاج يوم النحر؟", ["جمرة العقبة وحدها بسبع حصيات", "الجمرات الثلاث كل واحدة بسبع", "الجمرة الصغرى وحدها بسبع", "جمرة العقبة وحدها بثلاث حصيات"], "رمى النبي ﷺ يوم النحر جمرة العقبة وحدها بسبع حصيات يكبّر مع كل حصاة، أما الجمرات الثلاث فتُرمى في أيام التشريق."] },

  { id: "fqz-062", s: "fiqh", g: 1, d: 2, t: ["ihram-prohibitions"], src: "al-Bukhārī and Muslim, Kitāb al-Ḥajj (hadith of Ibn ʿUmar on what the muḥrim wears)", tr: ["ijma"],
    en: ["Which of the following is forbidden for a man in the state of iḥrām?", ["Wearing a shirt or trousers", "Wearing a waist wrap (izār)", "Wearing sandals", "Washing with plain water"], "The Prophet ﷺ named shirts, turbans, trousers, hooded cloaks and leather socks as garments the muḥrim does not wear. The man wears a waist wrap and an upper wrap, and sandals and washing are permitted."],
    de: ["Welche der folgenden Handlungen ist einem Mann im Iḥrām verboten?", ["Ein Hemd oder eine Hose tragen", "Ein Hüfttuch (Izār) tragen", "Sandalen tragen", "Sich mit klarem Wasser waschen"], "Der Prophet ﷺ nannte Hemden, Turbane, Hosen, Kapuzenmäntel und Lederstrümpfe als Kleidung, die der Muḥrim nicht trägt. Der Mann trägt ein Hüft- und ein Schultertuch; Sandalen und Waschen sind erlaubt."],
    ar: ["أيّ مما يلي محظور على الرجل المحرم؟", ["لبس القميص أو السراويل", "لبس الإزار", "لبس النعلين", "الاغتسال بالماء"], "ذكر النبي ﷺ أن المحرم لا يلبس القمص ولا العمائم ولا السراويلات ولا البرانس ولا الخفاف، ويلبس الرجل إزارًا ورداءً، ويباح له النعلان والاغتسال."] },

  { id: "fqz-063", s: "fiqh", g: 1, d: 2, t: ["hajj-types"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ḥajj, on the three types; al-Nawawī, Minhāj al-Ṭālibīn", tr: ["ijma"],
    en: ["What is the name of the type of ḥajj in which the pilgrim enters iḥrām for ʿumra and ḥajj together and stays in iḥrām until the Day of Sacrifice?", ["Qirān", "Tamattuʿ", "Ifrād", "Iḥṣār"], "Qirān joins ʿumra and ḥajj in one iḥrām. In tamattuʿ the pilgrim completes ʿumra, leaves iḥrām and then enters it again for ḥajj; in ifrād he enters iḥrām for ḥajj alone. Iḥṣār is being prevented from completing the rites."],
    de: ["Wie heißt die Form des Ḥaǧǧ, bei der der Pilger den Iḥrām für ʿUmra und Ḥaǧǧ zusammen antritt und bis zum Opfertag im Iḥrām bleibt?", ["Qirān", "Tamattuʿ", "Ifrād", "Iḥṣār"], "Qirān verbindet ʿUmra und Ḥaǧǧ in einem Iḥrām. Beim Tamattuʿ vollendet der Pilger die ʿUmra, verlässt den Iḥrām und tritt ihn dann für den Ḥaǧǧ erneut an; beim Ifrād tritt er ihn nur für den Ḥaǧǧ an. Iḥṣār ist das Gehindertwerden an der Vollendung der Riten."],
    ar: ["ما اسم النسك الذي يحرم فيه الحاج بالعمرة والحج معًا ويبقى محرمًا إلى يوم النحر؟", ["القِران", "التمتع", "الإفراد", "الإحصار"], "القران الجمع بين العمرة والحج بإحرام واحد، والتمتع أن يعتمر ثم يحلّ ثم يحرم بالحج، والإفراد الإحرام بالحج وحده، أما الإحصار فهو المنع من إتمام النسك."] },

  { id: "fqz-064", s: "fiqh", g: 2, d: 2, t: ["hajj-types", "tamattu"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ḥajj, on tamattuʿ", v: "2:196", tr: ["ijma"],
    en: ["Which description fits tamattuʿ, mentioned in the verse shown?", ["ʿUmra in the months of ḥajj, leaving iḥrām, then ḥajj in the same year", "ʿUmra after the ḥajj, in the month of Muḥarram", "Ḥajj alone without any ʿumra", "ʿUmra and ḥajj together in one iḥrām"], "Tamattuʿ means performing ʿumra in the months of ḥajj, enjoying the release from iḥrām, then entering iḥrām for ḥajj in the same year. The verse makes a sacrificial animal due for it from those who are not residents of the Sacred Mosque."],
    de: ["Welche Beschreibung passt auf den in der angezeigten Āya erwähnten Tamattuʿ?", ["ʿUmra in den Ḥaǧǧ-Monaten, Verlassen des Iḥrām, dann Ḥaǧǧ im selben Jahr", "ʿUmra nach dem Ḥaǧǧ im Monat Muḥarram", "Ḥaǧǧ allein ohne ʿUmra", "ʿUmra und Ḥaǧǧ zusammen in einem Iḥrām"], "Tamattuʿ bedeutet, in den Ḥaǧǧ-Monaten die ʿUmra zu verrichten, die Lösung vom Iḥrām zu genießen und dann im selben Jahr den Iḥrām für den Ḥaǧǧ anzutreten. Die Āya macht dafür ein Opfertier fällig, außer für die Anwohner der Heiligen Moschee."],
    ar: ["أيّ وصف ينطبق على التمتع المذكور في الآية المعروضة؟", ["أن يعتمر في أشهر الحج ثم يحلّ ثم يحج من عامه", "أن يعتمر بعد الحج في المحرّم", "أن يحج وحده بلا عمرة", "أن يجمع العمرة والحج بإحرام واحد"], "التمتع أن يأتي بالعمرة في أشهر الحج ويتحلل منها ثم يحرم بالحج من عامه، وأوجبت الآية فيه الهدي على من لم يكن أهله حاضري المسجد الحرام."] },

  { id: "fqz-065", s: "fiqh", g: 2, d: 3, t: ["hady", "tamattu"], src: "Ibn Kathīr, Tafsīr, on 2:196; Ibn Qudāma, al-Mughnī", v: "2:196", tr: ["ijma"],
    en: ["According to the verse shown, what must a pilgrim on tamattuʿ do if he cannot find a sacrificial animal?", ["Fast three days during the ḥajj and seven after returning", "Feed sixty poor people", "Fast two consecutive months", "Fast ten days before entering iḥrām"], "The verse prescribes three days of fasting during the ḥajj and seven upon return, ten complete days, for the one who finds no hady."],
    de: ["Was muss nach der angezeigten Āya ein Pilger mit Tamattuʿ tun, wenn er kein Opfertier findet?", ["Drei Tage während des Ḥaǧǧ und sieben nach der Rückkehr fasten", "Sechzig Arme speisen", "Zwei aufeinanderfolgende Monate fasten", "Zehn Tage vor dem Iḥrām fasten"], "Die Āya schreibt für den, der kein Hady findet, drei Fastentage während des Ḥaǧǧ und sieben nach der Rückkehr vor, zusammen zehn volle Tage."],
    ar: ["بحسب الآية المعروضة، ماذا يجب على المتمتع إذا لم يجد الهدي؟", ["صيام ثلاثة أيام في الحج وسبعة إذا رجع", "إطعام ستين مسكينًا", "صيام شهرين متتابعين", "صيام عشرة أيام قبل الإحرام"], "نصّت الآية على أن من لم يجد الهدي فصيام ثلاثة أيام في الحج وسبعة إذا رجع، تلك عشرة كاملة."] },

  { id: "fqz-066", s: "fiqh", g: 2, d: 2, t: ["miqat"], src: "al-Bukhārī and Muslim, Kitāb al-Ḥajj (hadith of Ibn ʿAbbās on the mawāqīt)", tr: ["ijma"],
    en: ["Which mīqāt did the Prophet ﷺ appoint for the people of Yemen?", ["Yalamlam", "Qarn al-Manāzil", "Dhū al-Ḥulayfa", "al-Juḥfa"], "Yalamlam is the mīqāt of the people of Yemen in the hadith of Ibn ʿAbbās. Qarn al-Manāzil is for Najd, Dhū al-Ḥulayfa for Medina and al-Juḥfa for al-Shām."],
    de: ["Welchen Mīqāt bestimmte der Prophet ﷺ für die Leute des Jemen?", ["Yalamlam", "Qarn al-Manāzil", "Ḏū l-Ḥulaifa", "al-Ǧuḥfa"], "Yalamlam ist im Hadith von Ibn ʿAbbās der Mīqāt der Leute des Jemen. Qarn al-Manāzil gilt für Naǧd, Ḏū l-Ḥulaifa für Medina und al-Ǧuḥfa für aš-Šām."],
    ar: ["ما الميقات الذي وقّته النبي ﷺ لأهل اليمن؟", ["يلملم", "قرن المنازل", "ذو الحليفة", "الجحفة"], "يلملم ميقات أهل اليمن في حديث ابن عباس، وقرن المنازل لأهل نجد، وذو الحليفة لأهل المدينة، والجحفة لأهل الشام."] },

  { id: "fqz-067", s: "fiqh", g: 2, d: 3, t: ["miqat"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Ḥajj, bāb Dhāt ʿIrq li-ahl al-ʿIrāq",
    en: ["According to a report in Ṣaḥīḥ al-Bukhārī, who designated Dhāt ʿIrq as the mīqāt for the people of Iraq?", ["ʿUmar ibn al-Khaṭṭāb", "ʿAlī ibn Abī Ṭālib", "Muʿāwiya ibn Abī Sufyān", "ʿUthmān ibn ʿAffān"], "Al-Bukhārī reports from Ibn ʿUmar that when Basra and Kufa were founded, their people came to ʿUmar, who fixed Dhāt ʿIrq for them as level with Qarn al-Manāzil. A report in Muslim attributes it to the Prophet ﷺ with the narrator expressing doubt."],
    de: ["Wer bestimmte nach einem Bericht in Ṣaḥīḥ al-Buḫārī Ḏāt ʿIrq als Mīqāt für die Leute des Irak?", ["ʿUmar ibn al-Ḫaṭṭāb", "ʿAlī ibn Abī Ṭālib", "Muʿāwiya ibn Abī Sufyān", "ʿUṯmān ibn ʿAffān"], "Al-Buḫārī berichtet von Ibn ʿUmar, dass nach der Gründung von Basra und Kufa deren Leute zu ʿUmar kamen, der ihnen Ḏāt ʿIrq auf der Höhe von Qarn al-Manāzil festlegte. Ein Bericht bei Muslim schreibt es dem Propheten ﷺ zu, wobei der Überlieferer Zweifel äußert."],
    ar: ["بحسب أثر في صحيح البخاري، مَن الذي حدّ ذات عرق ميقاتًا لأهل العراق؟", ["عمر بن الخطاب", "علي بن أبي طالب", "معاوية بن أبي سفيان", "عثمان بن عفان"], "روى البخاري عن ابن عمر أنه لما فُتح المصران أتوا عمر فحدّ لهم ذات عرق حذو قرن المنازل، وفي صحيح مسلم رواية ترفعه إلى النبي ﷺ مع شكّ الراوي في رفعه."] },

  { id: "fqz-068", s: "fiqh", g: 2, d: 2, t: ["muzdalifa"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ḥajj (hadith of Jābir); Ibn Qudāma, al-Mughnī", tr: ["ijma"],
    en: ["What do the pilgrims do with the Maghrib and ʿIshāʾ prayers on the night they reach Muzdalifa?", ["They combine them at Muzdalifa in the time of ʿIshāʾ", "They pray Maghrib at ʿArafa and ʿIshāʾ at Muzdalifa", "They combine them at ʿArafa before leaving", "They pray each in its own time at Minā"], "Following the Sunna, the pilgrims delay Maghrib and pray it with ʿIshāʾ upon reaching Muzdalifa, as Jābir describes the Prophet ﷺ doing."],
    de: ["Was tun die Pilger mit dem Maġrib- und dem ʿIšāʾ-Gebet in der Nacht, in der sie Muzdalifa erreichen?", ["Sie legen sie in Muzdalifa in der Zeit des ʿIšāʾ zusammen", "Sie beten Maġrib in ʿArafa und ʿIšāʾ in Muzdalifa", "Sie legen sie vor dem Aufbruch in ʿArafa zusammen", "Sie beten jedes zu seiner Zeit in Minā"], "Gemäß der Sunna verschieben die Pilger das Maġrib und beten es zusammen mit dem ʿIšāʾ, wenn sie Muzdalifa erreichen, wie Ǧābir es vom Propheten ﷺ beschreibt."],
    ar: ["ماذا يفعل الحجاج بصلاتي المغرب والعشاء ليلة وصولهم إلى مزدلفة؟", ["يجمعونهما بمزدلفة جمع تأخير", "يصلّون المغرب بعرفة والعشاء بمزدلفة", "يجمعونهما بعرفة قبل الدفع", "يصلّون كلًّا في وقتها بمنى"], "السنة أن يؤخر الحاج المغرب فيجمعها مع العشاء إذا وصل مزدلفة، كما وصف جابر فعل النبي ﷺ."] },

  { id: "fqz-069", s: "fiqh", g: 2, d: 3, t: ["ihram-prohibitions", "women-in-hajj"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Jazāʾ al-Ṣayd (hadith of Ibn ʿUmar)", tr: ["jumhur"],
    en: ["Which two items does the hadith of Ibn ʿUmar in Ṣaḥīḥ al-Bukhārī forbid to a woman in iḥrām?", ["A face veil (niqāb) and gloves", "Stitched clothing and shoes", "A headscarf and socks", "Coloured garments and jewellery"], "The hadith states that the woman in iḥrām does not wear the niqāb or gloves. Unlike a man, she may wear stitched clothing, cover her head and wear shoes."],
    de: ["Welche zwei Dinge verbietet der Hadith von Ibn ʿUmar in Ṣaḥīḥ al-Buḫārī einer Frau im Iḥrām?", ["Einen Gesichtsschleier (Niqāb) und Handschuhe", "Genähte Kleidung und Schuhe", "Ein Kopftuch und Socken", "Farbige Kleidung und Schmuck"], "Der Hadith besagt, dass die Frau im Iḥrām keinen Niqāb und keine Handschuhe trägt. Anders als der Mann darf sie genähte Kleidung tragen, den Kopf bedecken und Schuhe tragen."],
    ar: ["ما الشيئان اللذان نهى عنهما حديث ابن عمر في صحيح البخاري المرأةَ المحرمة؟", ["النقاب والقفازان", "المخيط والحذاء", "الخمار والجوارب", "الثياب الملوّنة والحليّ"], "في الحديث: لا تنتقب المرأة المحرمة ولا تلبس القفازين، ويجوز لها بخلاف الرجل لبس المخيط وتغطية الرأس ولبس الخف."] },

  { id: "fqz-070", s: "fiqh", g: 2, d: 3, t: ["fidya", "ihram-prohibitions"], src: "al-Bukhārī and Muslim, Kitāb al-Ḥajj (hadith of Kaʿb ibn ʿUjra); Ibn Kathīr, Tafsīr, on 2:196", v: "2:196", tr: ["jumhur"],
    en: ["A pilgrim in iḥrām shaves his head because of an ailment. According to the verse shown and the hadith of Kaʿb ibn ʿUjra, what is due?", ["A choice between fasting three days, feeding six poor people, or sacrificing a sheep", "Only a sheep, with no alternative", "Fasting ten days without alternative", "Nothing, since he had an excuse"], "The verse gives the options of fasting, charity or a sacrifice, and the hadith of Kaʿb ibn ʿUjra explains them as three days of fasting, feeding six poor people (half a ṣāʿ each) or one sheep. The pilgrim may choose, because the excuse lifts the sin but not the compensation."],
    de: ["Ein Pilger im Iḥrām rasiert sich wegen eines Leidens den Kopf. Was ist nach der angezeigten Āya und dem Hadith von Kaʿb ibn ʿUǧra fällig?", ["Die Wahl zwischen drei Fastentagen, der Speisung von sechs Armen oder dem Opfer eines Schafes", "Nur ein Schaf, ohne Alternative", "Zehn Fastentage ohne Alternative", "Nichts, da er einen Grund hatte"], "Die Āya nennt Fasten, Almosen oder ein Opfer, und der Hadith von Kaʿb ibn ʿUǧra erklärt sie als drei Fastentage, die Speisung von sechs Armen (je ein halbes Ṣāʿ) oder ein Schaf. Der Pilger darf wählen; der Grund hebt die Sünde auf, nicht aber den Ausgleich."],
    ar: ["حلق المحرم رأسه لأذى به، فما الواجب عليه بحسب الآية المعروضة وحديث كعب بن عجرة؟", ["التخيير بين صيام ثلاثة أيام أو إطعام ستة مساكين أو ذبح شاة", "شاة فقط بلا بديل", "صيام عشرة أيام بلا بديل", "لا شيء عليه لأنه معذور"], "ذكرت الآية الصيام أو الصدقة أو النسك، وبيّنها حديث كعب بن عجرة بصيام ثلاثة أيام أو إطعام ستة مساكين لكل مسكين نصف صاع أو ذبح شاة، فهو مخيّر، والعذر يرفع الإثم لا الفدية."] },

  { id: "fqz-071", s: "fiqh", g: 2, d: 2, t: ["ihram-prohibitions", "hunting"], src: "Ibn Kathīr, Tafsīr, on 5:95; Ibn Qudāma, al-Mughnī, Bāb Jazāʾ al-Ṣayd", v: "5:95", tr: ["ijma"],
    en: ["What does the verse shown forbid to those in the state of iḥrām?", ["Killing land game", "Fishing in the sea", "Slaughtering livestock for food", "Eating meat bought in the market"], "The verse forbids killing game while in iḥrām and sets a compensation for doing so deliberately. Sea game is permitted to the muḥrim by a following verse, and slaughtering domestic livestock is not hunting."],
    de: ["Was verbietet die angezeigte Āya denen, die sich im Iḥrām befinden?", ["Das Töten von Landwild", "Das Fischen im Meer", "Das Schlachten von Nutzvieh zum Essen", "Das Essen von auf dem Markt gekauftem Fleisch"], "Die Āya verbietet das Töten von Wild im Iḥrām und legt für die absichtliche Tat einen Ausgleich fest. Meerestiere sind dem Muḥrim nach einer folgenden Āya erlaubt, und das Schlachten von Haustieren ist keine Jagd."],
    ar: ["ماذا تحرّم الآية المعروضة على المحرمين؟", ["قتل صيد البر", "صيد البحر", "ذبح بهيمة الأنعام للأكل", "أكل اللحم المشترى من السوق"], "حرّمت الآية قتل الصيد حال الإحرام وأوجبت الجزاء على المتعمد، وأُحلّ صيد البحر للمحرم في الآية التي تليها، وذبح الأنعام ليس صيدًا."] },

  { id: "fqz-072", s: "fiqh", g: 2, d: 2, t: ["hajj-conditions", "child-hajj"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ḥajj (hadith of Ibn ʿAbbās); Ibn al-Mundhir, al-Ijmāʿ", tr: ["ijma"],
    en: ["A child performs ḥajj with his parents and later reaches puberty. What is the ruling?", ["His ḥajj was valid and rewarded, but he must perform the obligatory ḥajj after puberty", "His ḥajj was invalid and brings no reward", "His ḥajj fulfils the obligation, so he owes no further ḥajj", "His parents must perform a second ḥajj on his behalf"], "When a woman lifted up a child and asked whether he had a ḥajj, the Prophet ﷺ said yes, and that she would have a reward (Ṣaḥīḥ Muslim). The scholars agree that it does not replace the obligatory ḥajj, which becomes due once he is adult and able."],
    de: ["Ein Kind verrichtet mit seinen Eltern den Ḥaǧǧ und wird später geschlechtsreif. Was gilt?", ["Sein Ḥaǧǧ war gültig und belohnt, doch nach der Pubertät muss er den Pflicht-Ḥaǧǧ verrichten", "Sein Ḥaǧǧ war ungültig und ohne Lohn", "Sein Ḥaǧǧ erfüllt die Pflicht, er schuldet keinen weiteren", "Seine Eltern müssen für ihn einen zweiten Ḥaǧǧ verrichten"], "Als eine Frau ein Kind hochhob und fragte, ob es einen Ḥaǧǧ habe, bejahte der Prophet ﷺ und sagte, sie habe Lohn (Ṣaḥīḥ Muslim). Die Gelehrten sind sich einig, dass er den Pflicht-Ḥaǧǧ nicht ersetzt, der fällig wird, sobald er erwachsen und fähig ist."],
    ar: ["حجّ صبيّ مع والديه ثم بلغ، فما الحكم؟", ["حجّه صحيح مأجور، وعليه حجة الإسلام بعد البلوغ", "حجّه باطل لا أجر فيه", "حجّه يجزئه عن الفريضة فلا حج عليه", "على والديه أن يحجا عنه حجة ثانية"], "رفعت امرأة صبيًّا فقالت: ألهذا حج؟ قال: نعم ولكِ أجر، رواه مسلم، وأجمع العلماء على أنه لا يجزئه عن حجة الإسلام إذا بلغ واستطاع."] },

  { id: "fqz-073", s: "fiqh", g: 2, d: 3, t: ["tahallul", "hajj-rites"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ḥajj, on the first taḥallul", tr: ["ijma"],
    en: ["After the first release from iḥrām (al-taḥallul al-awwal) on the Day of Sacrifice, what remains forbidden by agreement until ṭawāf al-ifāḍa?", ["Intercourse with one's spouse", "Wearing ordinary clothes", "Clipping the nails", "Shaving or shortening the hair"], "After the first release the pilgrim may wear ordinary clothes and cut hair and nails, but the scholars agree that marital intercourse remains forbidden until the second release, which comes with ṭawāf al-ifāḍa."],
    de: ["Was bleibt nach der ersten Lösung vom Iḥrām (at-taḥallul al-auwal) am Opfertag nach Übereinstimmung bis zum Ṭawāf al-Ifāḍa verboten?", ["Geschlechtsverkehr mit dem Ehepartner", "Das Tragen gewöhnlicher Kleidung", "Das Schneiden der Nägel", "Das Rasieren oder Kürzen der Haare"], "Nach der ersten Lösung darf der Pilger gewöhnliche Kleidung tragen sowie Haare und Nägel schneiden; die Gelehrten sind sich jedoch einig, dass der eheliche Verkehr bis zur zweiten Lösung mit dem Ṭawāf al-Ifāḍa verboten bleibt."],
    ar: ["بعد التحلل الأول يوم النحر، ما الذي يبقى محرّمًا باتفاق حتى طواف الإفاضة؟", ["الجماع", "لبس الثياب المعتادة", "تقليم الأظفار", "الحلق أو التقصير"], "يحلّ للحاج بالتحلل الأول اللباس وأخذ الشعر والظفر، واتفق العلماء على بقاء تحريم الجماع حتى التحلل الثاني بطواف الإفاضة."] },

  { id: "fqz-074", s: "fiqh", g: 2, d: 3, t: ["tawaf", "hajj-sunan"], src: "al-Bukhārī and Muslim, Kitāb al-Ḥajj (hadith of Ibn ʿUmar on ramal); Ibn Qudāma, al-Mughnī", tr: ["jumhur"],
    en: ["What is ramal, and in which circuits of the ṭawāf of arrival or ʿumra is it performed?", ["Brisk walking with short steps, in the first three circuits, for men", "Running at full speed, in all seven circuits, for men and women", "Walking slowly, in the last three circuits, for men", "Uncovering the right shoulder, in the last four circuits, for men"], "Ramal is a brisk walk with short steps, done by men in the first three circuits of a ṭawāf followed by saʿy, as Ibn ʿUmar described. Uncovering the right shoulder is a different sunna, iḍṭibāʿ."],
    de: ["Was ist Ramal, und in welchen Runden des Ankunfts- oder ʿUmra-Ṭawāf wird er ausgeführt?", ["Zügiges Gehen mit kurzen Schritten, in den ersten drei Runden, für Männer", "Rennen mit voller Geschwindigkeit, in allen sieben Runden, für Männer und Frauen", "Langsames Gehen, in den letzten drei Runden, für Männer", "Entblößen der rechten Schulter, in den letzten vier Runden, für Männer"], "Ramal ist ein zügiges Gehen mit kurzen Schritten, das Männer in den ersten drei Runden eines Ṭawāf ausführen, dem ein Saʿy folgt, wie Ibn ʿUmar beschrieb. Das Entblößen der rechten Schulter ist eine andere Sunna, der Iḍṭibāʿ."],
    ar: ["ما الرَّمَل، وفي أيّ أشواط طواف القدوم أو العمرة يكون؟", ["الإسراع في المشي مع مقاربة الخطى، في الأشواط الثلاثة الأولى، للرجال", "العدو الشديد في الأشواط السبعة للرجال والنساء", "المشي ببطء في الأشواط الثلاثة الأخيرة للرجال", "كشف المنكب الأيمن في الأشواط الأربعة الأخيرة للرجال"], "الرمل إسراع المشي مع مقاربة الخطى، يفعله الرجل في الأشواط الثلاثة الأولى من طواف يعقبه سعي كما وصف ابن عمر، أما كشف المنكب الأيمن فهو الاضطباع وهو سنة أخرى."] },

  { id: "fqz-075", s: "fiqh", g: 2, d: 2, t: ["arafa", "hajj-pillars"], src: "Abū Dāwūd, al-Tirmidhī, al-Nasāʾī and Ibn Mājah, Kitāb al-Manāsik (hadith of ʿAbd al-Raḥmān ibn Yaʿmar)", v: "2:198", w: 12, tr: ["ijma"],
    en: ["The highlighted word names the place of the central rite of ḥajj. Which short prophetic statement expresses its importance?", ["Ḥajj is ʿArafa", "Ḥajj is the ṭawāf", "Ḥajj is the sacrifice", "Ḥajj is the talbiya"], "The hadith of ʿAbd al-Raḥmān ibn Yaʿmar, reported in the Sunan, states that ḥajj is ʿArafa: whoever misses the standing there has missed the ḥajj. All schools treat it as a pillar that cannot be repaired by a sacrifice."],
    de: ["Das hervorgehobene Wort nennt den Ort des zentralen Ritus des Ḥaǧǧ. Welche kurze prophetische Aussage drückt seine Bedeutung aus?", ["Der Ḥaǧǧ ist ʿArafa", "Der Ḥaǧǧ ist der Ṭawāf", "Der Ḥaǧǧ ist das Opfer", "Der Ḥaǧǧ ist die Talbiya"], "Der Hadith von ʿAbd ar-Raḥmān ibn Yaʿmar in den Sunan besagt, dass der Ḥaǧǧ ʿArafa ist: Wer das Stehen dort verpasst, hat den Ḥaǧǧ verpasst. Alle Schulen behandeln es als Säule, die nicht durch ein Opfer ersetzt werden kann."],
    ar: ["الكلمة المظللة اسم موضع الركن الأعظم في الحج، فأيّ عبارة نبوية قصيرة تعبّر عن مكانته؟", ["الحج عرفة", "الحج الطواف", "الحج النحر", "الحج التلبية"], "في حديث عبد الرحمن بن يعمر عند أصحاب السنن: الحج عرفة، فمن فاته الوقوف بها فاته الحج، وهو ركن عند جميع المذاهب لا يُجبر بدم."] },

  { id: "fqz-076", s: "fiqh", g: 3, d: 3, t: ["muzdalifa"], src: "al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān, on 2:198; Muslim, Ṣaḥīḥ, Kitāb al-Ḥajj (hadith of Jābir)", v: "2:198", w: 16,
    en: ["The highlighted word, with the one after it, names a landmark where Allah is remembered after leaving ʿArafa. In which station of ḥajj does it lie?", ["Muzdalifa", "Minā", "ʿArafa", "Makka, at the Kaʿba"], "Al-Mashʿar al-Ḥarām is in Muzdalifa; in Jābir's hadith the Prophet ﷺ came to it after the dawn prayer and remained in supplication until it was very bright. Some scholars use the name for the whole of Muzdalifa."],
    de: ["Das hervorgehobene Wort nennt mit dem folgenden eine Stätte, an der nach dem Aufbruch von ʿArafa Allahs gedacht wird. In welcher Station des Ḥaǧǧ liegt sie?", ["Muzdalifa", "Minā", "ʿArafa", "Mekka, an der Kaʿba"], "Al-Mašʿar al-Ḥarām liegt in Muzdalifa; im Hadith von Ǧābir kam der Prophet ﷺ nach dem Morgengebet dorthin und verweilte im Bittgebet, bis es sehr hell wurde. Manche Gelehrte bezeichnen damit ganz Muzdalifa."],
    ar: ["الكلمة المظللة مع ما بعدها اسم مَعلم يُذكر الله عنده بعد الإفاضة من عرفات، ففي أيّ مشعر يقع؟", ["مزدلفة", "منى", "عرفة", "مكة عند الكعبة"], "المشعر الحرام بمزدلفة، وفي حديث جابر أتاه النبي ﷺ بعد صلاة الفجر فدعا حتى أسفر جدًّا، ومن العلماء من يطلقه على مزدلفة كلها."] },

  { id: "fqz-077", s: "fiqh", g: 3, d: 3, t: ["mina", "ramy"], src: "Ibn Kathīr, Tafsīr, on 2:203; Ibn Qudāma, al-Mughnī, on the early departure", v: "2:203", tr: ["jumhur"],
    en: ["The verse shown allows hastening in two days. According to the majority, what does this mean for the pilgrim at Minā?", ["He may leave Minā on the 12th after stoning, if he leaves before sunset", "He may skip the stoning on the 11th and 12th", "He may leave Minā on the 10th after the sacrifice", "He may leave on the 13th without stoning that day"], "The two days are the 11th and 12th of Dhū al-Ḥijja. Whoever stones on both and leaves Minā before sunset on the 12th is free of the third day; if the sun sets while he is still there, the majority require him to stay and stone on the 13th."],
    de: ["Die angezeigte Āya erlaubt die Eile in zwei Tagen. Was bedeutet das nach der Mehrheit für den Pilger in Minā?", ["Er darf Minā am 12. nach dem Steinigen verlassen, wenn er vor Sonnenuntergang aufbricht", "Er darf das Steinigen am 11. und 12. auslassen", "Er darf Minā am 10. nach dem Opfer verlassen", "Er darf am 13. ohne das Steinigen dieses Tages aufbrechen"], "Die zwei Tage sind der 11. und 12. Ḏū l-Ḥiǧǧa. Wer an beiden steinigt und Minā vor Sonnenuntergang am 12. verlässt, ist vom dritten Tag befreit; geht die Sonne unter, während er noch dort ist, muss er nach der Mehrheit bleiben und am 13. steinigen."],
    ar: ["تبيح الآية المعروضة التعجل في يومين، فما معنى ذلك للحاج بمنى عند الجمهور؟", ["أن ينفر من منى في الثاني عشر بعد الرمي قبل غروب الشمس", "أن يترك رمي الحادي عشر والثاني عشر", "أن ينفر من منى يوم العاشر بعد النحر", "أن ينفر يوم الثالث عشر دون رميه"], "اليومان هما الحادي عشر والثاني عشر، فمن رمى فيهما ونفر قبل غروب شمس الثاني عشر سقط عنه اليوم الثالث، فإن غربت وهو بمنى لزمه عند الجمهور المبيت ورمي الثالث عشر."] },

  { id: "fqz-078", s: "fiqh", g: 3, d: 3, t: ["hajj-pillars", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Ḥajj", tr: ["hanafi", "comparative"],
    en: ["According to the Ḥanafī school, how many pillars (arkān) does ḥajj have, and what are they?", ["Two: the standing at ʿArafa and ṭawāf al-ziyāra", "Four: iḥrām, the standing, ṭawāf and saʿy", "Five: iḥrām, the standing, ṭawāf, saʿy and shaving", "Three: iḥrām, the standing and ṭawāf"], "The Ḥanafīs count only the standing at ʿArafa and (most of) ṭawāf al-ziyāra as pillars; iḥrām is a condition and saʿy a wājib. The Mālikīs and Ḥanbalīs count four, and al-Nawawī's Minhāj counts five including shaving."],
    de: ["Wie viele Säulen (Arkān) hat der Ḥaǧǧ nach der ḥanafitischen Schule, und welche sind es?", ["Zwei: das Stehen in ʿArafa und der Ṭawāf az-Ziyāra", "Vier: Iḥrām, das Stehen, Ṭawāf und Saʿy", "Fünf: Iḥrām, das Stehen, Ṭawāf, Saʿy und Rasieren", "Drei: Iḥrām, das Stehen und Ṭawāf"], "Die Ḥanafiten zählen nur das Stehen in ʿArafa und (den größten Teil des) Ṭawāf az-Ziyāra zu den Säulen; der Iḥrām ist eine Bedingung und der Saʿy ein Wāǧib. Malikiten und Ḥanbaliten zählen vier, und an-Nawawīs Minhāǧ zählt fünf einschließlich des Rasierens."],
    ar: ["كم ركنًا للحج عند الحنفية، وما هي؟", ["ركنان: الوقوف بعرفة وطواف الزيارة", "أربعة: الإحرام والوقوف والطواف والسعي", "خمسة: الإحرام والوقوف والطواف والسعي والحلق", "ثلاثة: الإحرام والوقوف والطواف"], "الركن عند الحنفية الوقوف بعرفة وأكثر طواف الزيارة، والإحرام عندهم شرط والسعي واجب، وعدّها المالكية والحنابلة أربعة، وعدّها النووي في المنهاج خمسة بزيادة الحلق."] },

  { id: "fqz-079", s: "fiqh", g: 4, d: 4, t: ["say", "hajj-pillars", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Ḥajj; Ibn Qudāma, al-Mughnī, on the saʿy", tr: ["hanafi", "comparative"],
    en: ["Which school regards the saʿy between al-Ṣafā and al-Marwa as a wājib, whose omission is repaired by a sacrifice, rather than a pillar?", ["The Ḥanafī school", "The Mālikī school", "The Shāfiʿī school", "The Ḥanbalī school (its relied view)"], "The Ḥanafīs argue that the verse on al-Ṣafā and al-Marwa only lifts blame, which does not establish a pillar, so they rank saʿy as wājib with a sacrifice for omitting it. The Mālikīs, Shāfiʿīs and the relied Ḥanbalī view make it a pillar without which ḥajj is incomplete."],
    de: ["Welche Schule betrachtet den Saʿy zwischen aṣ-Ṣafā und al-Marwa als Wāǧib, dessen Unterlassung durch ein Opfer ausgeglichen wird, und nicht als Säule?", ["Die ḥanafitische Schule", "Die malikitische Schule", "Die šāfiʿitische Schule", "Die ḥanbalitische Schule (maßgebliche Ansicht)"], "Die Ḥanafiten argumentieren, dass die Āya über aṣ-Ṣafā und al-Marwa nur den Tadel aufhebt, was keine Säule begründet; daher gilt der Saʿy als Wāǧib mit einem Opfer bei Unterlassung. Malikiten, Šāfiʿiten und die maßgebliche ḥanbalitische Ansicht machen ihn zur Säule, ohne die der Ḥaǧǧ unvollständig ist."],
    ar: ["أيّ مذهب يجعل السعي بين الصفا والمروة واجبًا يُجبر بدم لا ركنًا؟", ["المذهب الحنفي", "المذهب المالكي", "المذهب الشافعي", "المذهب الحنبلي في المعتمد"], "احتج الحنفية بأن آية الصفا والمروة جاءت برفع الجناح وهو لا يفيد الركنية، فجعلوا السعي واجبًا يُجبر تركه بدم، وجعله المالكية والشافعية والمعتمد عند الحنابلة ركنًا لا يتم الحج إلا به."] },

  { id: "fqz-080", s: "fiqh", g: 3, d: 3, t: ["hajj-types", "school-differences"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ḥajj; Ibn Qudāma, al-Mughnī", tr: ["comparative", "hanafi", "maliki", "shafii", "hanbali"],
    en: ["Which statement correctly describes the schools' preference among the three types of ḥajj?", ["Ḥanafīs prefer qirān, Mālikīs and Shāfiʿīs ifrād, Ḥanbalīs tamattuʿ", "Ḥanafīs prefer tamattuʿ, Mālikīs and Shāfiʿīs qirān, Ḥanbalīs ifrād", "Ḥanafīs prefer ifrād, Mālikīs and Shāfiʿīs tamattuʿ, Ḥanbalīs qirān", "All four schools prefer qirān"], "The disagreement goes back to the reports about how the Prophet ﷺ performed his ḥajj. The Ḥanafīs prefer qirān, the Mālikīs and Shāfiʿīs ifrād (for the Shāfiʿīs when ʿumra is done the same year), and the Ḥanbalīs tamattuʿ, citing the Prophet's wish to have done it."],
    de: ["Welche Aussage beschreibt die Präferenz der Schulen unter den drei Formen des Ḥaǧǧ richtig?", ["Ḥanafiten bevorzugen Qirān, Malikiten und Šāfiʿiten Ifrād, Ḥanbaliten Tamattuʿ", "Ḥanafiten bevorzugen Tamattuʿ, Malikiten und Šāfiʿiten Qirān, Ḥanbaliten Ifrād", "Ḥanafiten bevorzugen Ifrād, Malikiten und Šāfiʿiten Tamattuʿ, Ḥanbaliten Qirān", "Alle vier Schulen bevorzugen Qirān"], "Der Unterschied geht auf die Berichte darüber zurück, wie der Prophet ﷺ seinen Ḥaǧǧ verrichtete. Die Ḥanafiten bevorzugen Qirān, Malikiten und Šāfiʿiten Ifrād (die Šāfiʿiten, wenn die ʿUmra im selben Jahr folgt) und die Ḥanbaliten Tamattuʿ, unter Verweis auf den Wunsch des Propheten, ihn so verrichtet zu haben."],
    ar: ["أيّ العبارات تصف تفضيل المذاهب بين أنساك الحج الثلاثة وصفًا صحيحًا؟", ["الحنفية القران، والمالكية والشافعية الإفراد، والحنابلة التمتع", "الحنفية التمتع، والمالكية والشافعية القران، والحنابلة الإفراد", "الحنفية الإفراد، والمالكية والشافعية التمتع، والحنابلة القران", "الأربعة يفضّلون القران"], "يرجع الخلاف إلى اختلاف الروايات في صفة حجة النبي ﷺ؛ ففضّل الحنفية القران، والمالكية والشافعية الإفراد (والشافعية إذا اعتمر من عامه)، والحنابلة التمتع لتمنّي النبي ﷺ أن لو جعلها عمرة."] },

  { id: "fqz-081", s: "fiqh", g: 3, d: 4, t: ["umra", "school-differences"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ḥajj, on the ʿumra; Ibn Qudāma, al-Mughnī", tr: ["comparative", "hanafi", "maliki", "shafii", "hanbali"],
    en: ["What is the ruling of ʿumra once in a lifetime according to the schools?", ["Shāfiʿīs and Ḥanbalīs: obligatory; Ḥanafīs and Mālikīs: an emphasised sunna", "Ḥanafīs and Mālikīs: obligatory; Shāfiʿīs and Ḥanbalīs: an emphasised sunna", "All four schools: obligatory every year", "All four schools: merely permitted"], "The Shāfiʿīs (in the more evident view) and Ḥanbalīs make ʿumra obligatory once, arguing from the command to complete ḥajj and ʿumra. The Ḥanafīs and Mālikīs hold it to be an emphasised sunna, since the verse obliging ḥajj on those able does not mention it."],
    de: ["Wie lautet nach den Schulen das Urteil über die ʿUmra einmal im Leben?", ["Šāfiʿiten und Ḥanbaliten: Pflicht; Ḥanafiten und Malikiten: bekräftigte Sunna", "Ḥanafiten und Malikiten: Pflicht; Šāfiʿiten und Ḥanbaliten: bekräftigte Sunna", "Alle vier Schulen: jedes Jahr Pflicht", "Alle vier Schulen: lediglich erlaubt"], "Die Šāfiʿiten (nach der deutlicheren Ansicht) und die Ḥanbaliten machen die ʿUmra einmal zur Pflicht und berufen sich auf das Gebot, Ḥaǧǧ und ʿUmra zu vollenden. Ḥanafiten und Malikiten halten sie für eine bekräftigte Sunna, da die Āya, die den Ḥaǧǧ den Fähigen auferlegt, sie nicht erwähnt."],
    ar: ["ما حكم العمرة مرة في العمر عند المذاهب؟", ["الشافعية والحنابلة: واجبة، والحنفية والمالكية: سنة مؤكدة", "الحنفية والمالكية: واجبة، والشافعية والحنابلة: سنة مؤكدة", "الأربعة: واجبة كل عام", "الأربعة: مباحة فقط"], "أوجبها الشافعية في الأظهر والحنابلة مرة في العمر استدلالًا بالأمر بإتمام الحج والعمرة، وجعلها الحنفية والمالكية سنة مؤكدة لأن آية فرض الحج على المستطيع لم تذكرها."] },

  { id: "fqz-082", s: "fiqh", g: 3, d: 3, t: ["farewell-tawaf", "women-in-hajj"], src: "al-Bukhārī and Muslim, Kitāb al-Ḥajj (hadith of Ibn ʿAbbās); Ibn Qudāma, al-Mughnī", tr: ["ijma"],
    en: ["A woman's menstruation begins after she has performed ṭawāf al-ifāḍa, and her group is leaving Makka. What does the hadith of Ibn ʿAbbās say about the farewell ṭawāf?", ["She is excused from it and may leave without it", "She must wait in Makka until she is pure", "She must offer a sacrifice in its place", "She performs it while menstruating"], "Ibn ʿAbbās reported that people were commanded to make their last act at the House, except that it was lightened for the menstruating woman. The Prophet ﷺ also allowed Ṣafiyya to depart once he learned she had already done ṭawāf al-ifāḍa."],
    de: ["Bei einer Frau beginnt die Menstruation, nachdem sie den Ṭawāf al-Ifāḍa verrichtet hat, und ihre Gruppe verlässt Mekka. Was sagt der Hadith von Ibn ʿAbbās über den Abschieds-Ṭawāf?", ["Sie ist davon befreit und darf ohne ihn abreisen", "Sie muss in Mekka warten, bis sie rein ist", "Sie muss an seiner Stelle ein Opfer darbringen", "Sie verrichtet ihn während der Menstruation"], "Ibn ʿAbbās berichtete, dass den Menschen befohlen wurde, ihr Letztes am Haus zu verrichten, nur für die menstruierende Frau wurde es erleichtert. Auch Ṣafiyya erlaubte der Prophet ﷺ abzureisen, als er erfuhr, dass sie den Ṭawāf al-Ifāḍa schon verrichtet hatte."],
    ar: ["حاضت امرأة بعد أن طافت طواف الإفاضة، ورفقتها تغادر مكة، فماذا يقول حديث ابن عباس في طواف الوداع؟", ["يسقط عنها وتنصرف بلا وداع", "تنتظر بمكة حتى تطهر", "تذبح شاة بدلًا منه", "تطوف وهي حائض"], "قال ابن عباس: أُمر الناس أن يكون آخر عهدهم بالبيت إلا أنه خُفّف عن الحائض، وأذن النبي ﷺ لصفية بالنفر لما علم أنها قد أفاضت."] },

  { id: "fqz-083", s: "fiqh", g: 3, d: 4, t: ["hajj-conditions", "women-in-hajj", "school-differences"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ḥajj; Khalīl, al-Mukhtaṣar; al-Nawawī, Minhāj al-Ṭālibīn", tr: ["comparative", "hanafi", "maliki", "shafii", "hanbali"],
    en: ["Which statement correctly describes the disagreement about a woman travelling for her obligatory ḥajj without a maḥram?", ["Mālikīs and Shāfiʿīs accept trustworthy company in its place; Ḥanafīs and Ḥanbalīs require a maḥram or husband", "Ḥanafīs and Ḥanbalīs accept trustworthy company; Mālikīs and Shāfiʿīs require a maḥram", "All four schools accept travelling entirely alone", "All four schools forbid her ḥajj in every case"], "The Ḥanafīs and Ḥanbalīs make a maḥram or husband part of her ability (istiṭāʿa), following the hadith forbidding a woman to travel without a maḥram. The Mālikīs and Shāfiʿīs allow her, for the obligatory ḥajj, to travel with a safe and trustworthy group, such as reliable women."],
    de: ["Welche Aussage beschreibt den Meinungsunterschied darüber, ob eine Frau zu ihrem Pflicht-Ḥaǧǧ ohne Maḥram reisen darf, richtig?", ["Malikiten und Šāfiʿiten lassen eine vertrauenswürdige Reisegruppe genügen; Ḥanafiten und Ḥanbaliten verlangen einen Maḥram oder den Ehemann", "Ḥanafiten und Ḥanbaliten lassen eine vertrauenswürdige Gruppe genügen; Malikiten und Šāfiʿiten verlangen einen Maḥram", "Alle vier Schulen erlauben eine völlig allein unternommene Reise", "Alle vier Schulen verbieten ihren Ḥaǧǧ in jedem Fall"], "Ḥanafiten und Ḥanbaliten zählen einen Maḥram oder Ehemann zu ihrer Fähigkeit (Istiṭāʿa), gemäß dem Hadith, der einer Frau das Reisen ohne Maḥram verbietet. Malikiten und Šāfiʿiten erlauben ihr für den Pflicht-Ḥaǧǧ die Reise mit einer sicheren und vertrauenswürdigen Gruppe, etwa zuverlässigen Frauen."],
    ar: ["أيّ العبارات تصف الخلاف في سفر المرأة لحجة الإسلام بلا محرم وصفًا صحيحًا؟", ["المالكية والشافعية: تكفي الرفقة المأمونة، والحنفية والحنابلة: يشترط المحرم أو الزوج", "الحنفية والحنابلة: تكفي الرفقة المأمونة، والمالكية والشافعية: يشترط المحرم", "الأربعة: يجوز سفرها وحدها مطلقًا", "الأربعة: يمنع حجها بكل حال"], "جعل الحنفية والحنابلة المحرم أو الزوج من الاستطاعة في حقها لحديث النهي عن سفر المرأة بلا محرم، وأجاز المالكية والشافعية لها في حجة الفرض السفر مع رفقة مأمونة كنسوة ثقات."] },

  { id: "fqz-084", s: "fiqh", g: 3, d: 4, t: ["ramy", "mina"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Ḥajj (hadith of Ibn ʿUmar); Muslim, Ṣaḥīḥ (hadith of Jābir on the time of stoning)", tr: ["jumhur"],
    en: ["On the days of tashrīq, in what order and from what time are the three jamarāt stoned according to the Sunna?", ["The small, then the middle, then Jamrat al-ʿAqaba, after the sun passes the meridian", "Jamrat al-ʿAqaba, then the middle, then the small, after dawn", "The middle, then the small, then Jamrat al-ʿAqaba, after sunrise", "The small, then Jamrat al-ʿAqaba, then the middle, after ʿAṣr"], "Ibn ʿUmar described stoning the jamra nearest the mosque of al-Khayf first, then the middle one, then Jamrat al-ʿAqaba, standing in supplication after the first two, and attributed this to the Prophet ﷺ. Jābir reported that on these days the Prophet ﷺ stoned after the sun had declined."],
    de: ["In welcher Reihenfolge und ab welcher Zeit werden an den Tašrīq-Tagen die drei Ǧamarāt nach der Sunna beworfen?", ["Die kleine, dann die mittlere, dann die Ǧamrat al-ʿAqaba, nach dem Mittagsscheitel der Sonne", "Die Ǧamrat al-ʿAqaba, dann die mittlere, dann die kleine, nach der Morgendämmerung", "Die mittlere, dann die kleine, dann die Ǧamrat al-ʿAqaba, nach Sonnenaufgang", "Die kleine, dann die Ǧamrat al-ʿAqaba, dann die mittlere, nach dem ʿAṣr"], "Ibn ʿUmar beschrieb, zuerst die der Moschee al-Ḫaif nächstgelegene Ǧamra zu bewerfen, dann die mittlere, dann die Ǧamrat al-ʿAqaba, mit Bittgebet nach den ersten beiden, und führte dies auf den Propheten ﷺ zurück. Ǧābir berichtete, dass der Prophet ﷺ an diesen Tagen nach dem Überschreiten des Mittagsscheitels warf."],
    ar: ["في أيام التشريق، بأيّ ترتيب ومن أيّ وقت تُرمى الجمرات الثلاث في السنة؟", ["الصغرى ثم الوسطى ثم جمرة العقبة بعد الزوال", "جمرة العقبة ثم الوسطى ثم الصغرى بعد الفجر", "الوسطى ثم الصغرى ثم جمرة العقبة بعد طلوع الشمس", "الصغرى ثم جمرة العقبة ثم الوسطى بعد العصر"], "وصف ابن عمر رمي الجمرة الدنيا ثم الوسطى ثم جمرة العقبة مع الوقوف للدعاء بعد الأوليين، ورفعه إلى النبي ﷺ، وروى جابر أن النبي ﷺ رمى في هذه الأيام إذا زالت الشمس."] },

  { id: "fqz-085", s: "fiqh", g: 3, d: 3, t: ["hajj-months", "school-differences"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ḥajj; Ibn Kathīr, Tafsīr, on 2:197", v: "2:197", tr: ["maliki", "comparative"],
    en: ["The verse shown speaks of the known months of ḥajj. Which school counts the whole of Dhū al-Ḥijja among them, rather than only its first ten days?", ["The Mālikī school", "The Ḥanafī school", "The Shāfiʿī school", "The Ḥanbalī school"], "All agree that Shawwāl and Dhū al-Qaʿda are months of ḥajj. The Mālikīs include the whole of Dhū al-Ḥijja, taking the plural literally, while the Ḥanafīs and Ḥanbalīs count its first ten days and the Shāfiʿīs its first ten nights up to the dawn of the Day of Sacrifice."],
    de: ["Die angezeigte Āya spricht von den bekannten Monaten des Ḥaǧǧ. Welche Schule zählt den gesamten Ḏū l-Ḥiǧǧa dazu und nicht nur seine ersten zehn Tage?", ["Die malikitische Schule", "Die ḥanafitische Schule", "Die šāfiʿitische Schule", "Die ḥanbalitische Schule"], "Einig ist man, dass Šauwāl und Ḏū l-Qaʿda Monate des Ḥaǧǧ sind. Die Malikiten schließen den gesamten Ḏū l-Ḥiǧǧa ein, indem sie den Plural wörtlich nehmen; Ḥanafiten und Ḥanbaliten zählen seine ersten zehn Tage und die Šāfiʿiten seine ersten zehn Nächte bis zur Morgendämmerung des Opfertages."],
    ar: ["تذكر الآية المعروضة أشهر الحج المعلومات، فأيّ مذهب يعدّ ذا الحجة كله منها لا عشره الأوائل فقط؟", ["المذهب المالكي", "المذهب الحنفي", "المذهب الشافعي", "المذهب الحنبلي"], "اتفقوا على أن شوالًا وذا القعدة من أشهر الحج، وعدّ المالكية ذا الحجة كله منها أخذًا بظاهر الجمع، وعدّ الحنفية والحنابلة عشرة أيام منه، والشافعية عشر ليال إلى فجر يوم النحر."] },

  { id: "fqz-086", s: "fiqh", g: 3, d: 4, t: ["hady"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ḥajj (hadith of Jābir on sharing); Ibn Rushd, Bidāyat al-Mujtahid", tr: ["jumhur", "maliki"],
    en: ["According to the majority, based on the hadith of Jābir in Ṣaḥīḥ Muslim, how many people may share one camel or one cow as hady?", ["Seven", "Three", "Ten", "Two"], "Jābir reported that at al-Ḥudaybiya they sacrificed a camel for seven and a cow for seven. The majority therefore allow a seventh of a camel or cow to replace a sheep, while Mālik did not permit sharing in an obligatory hady."],
    de: ["Wie viele Personen dürfen sich nach der Mehrheit, gestützt auf den Hadith von Ǧābir in Ṣaḥīḥ Muslim, ein Kamel oder ein Rind als Hady teilen?", ["Sieben", "Drei", "Zehn", "Zwei"], "Ǧābir berichtete, dass sie in al-Ḥudaibiya ein Kamel für sieben und ein Rind für sieben opferten. Die Mehrheit lässt daher ein Siebtel eines Kamels oder Rindes an die Stelle eines Schafes treten, während Mālik die Teilung beim Pflicht-Hady nicht erlaubte."],
    ar: ["كم شخصًا يجوز أن يشتركوا في البدنة أو البقرة هديًا عند الجمهور بناءً على حديث جابر في صحيح مسلم؟", ["سبعة", "ثلاثة", "عشرة", "اثنان"], "قال جابر: نحرنا بالحديبية البدنة عن سبعة والبقرة عن سبعة، فأجاز الجمهور سُبع البدنة أو البقرة مكان الشاة، ولم يُجز مالك الاشتراك في الهدي الواجب."] },

  { id: "fqz-087", s: "fiqh", g: 4, d: 5, t: ["arafa", "hajj-pillars", "school-differences"], src: "Khalīl, al-Mukhtaṣar, Bāb al-Ḥajj; Ibn Rushd, Bidāyat al-Mujtahid", tr: ["maliki", "comparative"],
    en: ["In the Mālikī school, which part of the standing at ʿArafa is the pillar, and what is the status of the daytime standing?", ["Presence at ʿArafa for a moment of the night before the Day of Sacrifice is the pillar; the daytime standing is wājib", "The daytime standing after the meridian is the pillar; the night standing is a sunna", "Both day and night together form the pillar, neither alone suffices", "Standing from the dawn of the 9th is the pillar; the night is not counted"], "Khalīl defines the pillar as being present at ʿArafa for a moment on the night of the Day of Sacrifice, following the Prophet's practice of leaving only after sunset; the daytime standing is wājib and its omission is repaired by a sacrifice. For the majority, standing at any time between the 9th (from the meridian, or from dawn for the Ḥanbalīs) and the dawn of the 10th suffices."],
    de: ["Welcher Teil des Stehens in ʿArafa ist in der malikitischen Schule die Säule, und welchen Rang hat das Stehen am Tag?", ["Die Anwesenheit in ʿArafa für einen Augenblick der Nacht vor dem Opfertag ist die Säule; das Stehen am Tag ist Wāǧib", "Das Stehen am Tag nach dem Mittagsscheitel ist die Säule; das Stehen in der Nacht ist Sunna", "Tag und Nacht zusammen bilden die Säule, keines allein genügt", "Das Stehen ab der Morgendämmerung des 9. ist die Säule; die Nacht zählt nicht"], "Ḫalīl bestimmt als Säule die Anwesenheit in ʿArafa für einen Augenblick in der Nacht des Opfertages, gemäß der Praxis des Propheten, erst nach Sonnenuntergang aufzubrechen; das Stehen am Tag ist Wāǧib, seine Unterlassung wird durch ein Opfer ausgeglichen. Für die Mehrheit genügt das Stehen zu irgendeiner Zeit zwischen dem 9. (ab Mittagsscheitel, bei den Ḥanbaliten ab Morgendämmerung) und der Morgendämmerung des 10."],
    ar: ["ما الركن من الوقوف بعرفة عند المالكية، وما حكم الوقوف نهارًا؟", ["الركن الحضور بعرفة جزءًا من ليلة النحر، والوقوف نهارًا واجب", "الركن الوقوف نهارًا بعد الزوال، والوقوف ليلًا سنة", "الركن مجموع النهار والليل ولا يكفي أحدهما", "الركن الوقوف من فجر التاسع، ولا عبرة بالليل"], "نصّ خليل على أن الركن الحضور بجزء من عرفة ساعةً ليلة النحر اتباعًا لدفع النبي ﷺ بعد الغروب، وأن الوقوف نهارًا واجب يُجبر بدم، والجمهور على أن الوقوف في أي جزء من وقته يجزئ، من زوال التاسع أو من فجره عند الحنابلة إلى فجر العاشر."] },

  { id: "fqz-088", s: "fiqh", g: 4, d: 5, t: ["ihram-prohibitions", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Bāb al-Jināyāt; Ibn Qudāma, al-Mughnī, on intercourse in iḥrām", tr: ["hanafi", "jumhur", "comparative"],
    en: ["A pilgrim has intercourse with his wife after the standing at ʿArafa but before any release from iḥrām. Which statement correctly describes the disagreement?", ["Ḥanafīs: the ḥajj is not invalidated but a camel (badana) is due; the majority: the ḥajj is invalidated", "Ḥanafīs: the ḥajj is invalidated; the majority: only a sheep is due", "All schools: the ḥajj is valid and nothing is due", "All schools: the ḥajj is valid and only fasting is due"], "Al-Hidāya holds that intercourse after the standing does not invalidate the ḥajj, since its main pillar is already done, but requires a badana. The Mālikīs, Shāfiʿīs and Ḥanbalīs hold that intercourse before the first release invalidates the ḥajj, which must still be completed and made up, with a badana due."],
    de: ["Ein Pilger hat nach dem Stehen in ʿArafa, aber vor jeder Lösung vom Iḥrām Verkehr mit seiner Frau. Welche Aussage beschreibt den Meinungsunterschied richtig?", ["Ḥanafiten: Der Ḥaǧǧ wird nicht ungültig, aber ein Kamel (Badana) ist fällig; die Mehrheit: Der Ḥaǧǧ wird ungültig", "Ḥanafiten: Der Ḥaǧǧ wird ungültig; die Mehrheit: nur ein Schaf ist fällig", "Alle Schulen: Der Ḥaǧǧ ist gültig, nichts ist fällig", "Alle Schulen: Der Ḥaǧǧ ist gültig, nur Fasten ist fällig"], "Al-Hidāya hält, dass der Verkehr nach dem Stehen den Ḥaǧǧ nicht ungültig macht, da seine Hauptsäule bereits erfüllt ist, verlangt aber eine Badana. Malikiten, Šāfiʿiten und Ḥanbaliten halten, dass Verkehr vor der ersten Lösung den Ḥaǧǧ ungültig macht; er muss dennoch zu Ende geführt und nachgeholt werden, und eine Badana ist fällig."],
    ar: ["جامع حاجّ زوجته بعد الوقوف بعرفة وقبل التحلل الأول، فأيّ العبارات تصف الخلاف صحيحًا؟", ["الحنفية: لا يفسد حجه وعليه بدنة، والجمهور: يفسد حجه", "الحنفية: يفسد حجه، والجمهور: عليه شاة فقط", "الجميع: حجه صحيح ولا شيء عليه", "الجميع: حجه صحيح وعليه الصيام فقط"], "في الهداية: من جامع بعد الوقوف بعرفة لم يفسد حجه وعليه بدنة لأداء الركن الأعظم، وذهب المالكية والشافعية والحنابلة إلى فساد الحج بالجماع قبل التحلل الأول مع وجوب المضي فيه وقضائه وبدنة."] },

  { id: "fqz-089", s: "fiqh", g: 4, d: 4, t: ["tawaf", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Ḥajj and Bāb al-Jināyāt; Ibn Qudāma, al-Mughnī", tr: ["hanafi", "jumhur", "comparative"],
    en: ["How does the Ḥanafī school classify ritual purity (ṭahāra) for ṭawāf, in contrast to the majority?", ["As a wājib: ṭawāf without it is valid but requires a sacrifice or repetition", "As a condition: ṭawāf without it is void", "As merely recommended, with no consequence", "As a condition for men only"], "The majority make purity a condition of ṭawāf, likening it to prayer. The Ḥanafīs make it wājib: the ṭawāf counts, but a sheep is due (a badana for ṭawāf al-ziyāra in major impurity) unless it is repeated in purity."],
    de: ["Wie stuft die ḥanafitische Schule im Unterschied zur Mehrheit die rituelle Reinheit (Ṭahāra) für den Ṭawāf ein?", ["Als Wāǧib: Ṭawāf ohne sie ist gültig, verlangt aber ein Opfer oder Wiederholung", "Als Bedingung: Ṭawāf ohne sie ist nichtig", "Als lediglich empfohlen, ohne Folge", "Als Bedingung nur für Männer"], "Die Mehrheit macht die Reinheit zur Bedingung des Ṭawāf und vergleicht ihn mit dem Gebet. Die Ḥanafiten machen sie zum Wāǧib: Der Ṭawāf zählt, doch ein Schaf ist fällig (eine Badana beim Ṭawāf az-Ziyāra in großer Unreinheit), sofern er nicht in Reinheit wiederholt wird."],
    ar: ["كيف يصنّف الحنفية الطهارة للطواف خلافًا للجمهور؟", ["واجبة: يصح الطواف بدونها ويلزم دم أو الإعادة", "شرط: يبطل الطواف بدونها", "مستحبة فقط لا يترتب على تركها شيء", "شرط للرجال دون النساء"], "جعل الجمهور الطهارة شرطًا للطواف قياسًا على الصلاة، وجعلها الحنفية واجبة فيعتدّ بالطواف وتلزم شاة، وبدنة في طواف الزيارة جنبًا، ما لم يُعِده طاهرًا."] },

  { id: "fqz-090", s: "fiqh", g: 4, d: 4, t: ["hunting", "ihram-prohibitions", "school-differences"], src: "al-Marghīnānī, al-Hidāya, Bāb al-Jināyāt fī al-Ṣayd; Ibn Rushd, Bidāyat al-Mujtahid", v: "5:95", tr: ["hanafi", "jumhur", "comparative"],
    en: ["The verse shown sets a compensation, judged by two just men, for game killed in iḥrām. How did Abū Ḥanīfa understand it, in contrast to the majority?", ["As the value of the game, which may then be spent on a sacrifice, food or fasting", "As a livestock animal resembling the game in form", "As a fixed sum of money set by the ruler", "As fasting only, with no sacrifice"], "The majority, following the Companions' judgements, require a livestock animal resembling the game (mithl), e.g. a camel for an ostrich. Abū Ḥanīfa understood the equivalent as the value assessed by two just men, with which a sacrifice is bought or food given, or the person fasts in its place."],
    de: ["Die angezeigte Āya legt für im Iḥrām getötetes Wild einen von zwei gerechten Männern beurteilten Ausgleich fest. Wie verstand ihn Abū Ḥanīfa im Unterschied zur Mehrheit?", ["Als den Wert des Wildes, der dann für ein Opfer, Speisung oder Fasten verwendet wird", "Als ein Nutztier, das dem Wild der Gestalt nach ähnelt", "Als einen festen, vom Herrscher bestimmten Geldbetrag", "Als ausschließliches Fasten ohne Opfer"], "Die Mehrheit verlangt nach den Urteilen der Gefährten ein dem Wild ähnliches Nutztier (Miṯl), etwa ein Kamel für einen Strauß. Abū Ḥanīfa verstand das Gleichwertige als den von zwei Gerechten geschätzten Wert, mit dem ein Opfertier gekauft oder Speise gegeben wird, oder an dessen Stelle gefastet wird."],
    ar: ["تذكر الآية المعروضة جزاءً يحكم به ذوا عدل لصيد المحرم، فكيف فهمه أبو حنيفة خلافًا للجمهور؟", ["قيمة الصيد يُشترى بها هدي أو طعام أو يُصام عنها", "مثل الصيد من النعم في الخلقة", "مبلغ مقطوع يقدّره الإمام", "الصيام فقط بلا هدي"], "أوجب الجمهور المثل من النعم في الصورة كما حكم الصحابة كالبدنة في النعامة، وفسّر أبو حنيفة المثل بالقيمة يقوّمها عدلان ثم يشتري بها هديًا أو طعامًا أو يصوم بدلها."] },

  { id: "fqz-091", s: "fiqh", g: 4, d: 5, t: ["ihram-prohibitions", "school-differences"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Nikāḥ (hadith of ʿUthmān); al-Marghīnānī, al-Hidāya, Kitāb al-Nikāḥ; Ibn Rushd, Bidāyat al-Mujtahid", tr: ["hanafi", "jumhur", "comparative"],
    en: ["Which statement correctly describes the disagreement about a marriage contract concluded by a person in iḥrām?", ["The majority hold it invalid, citing the hadith of ʿUthmān in Ṣaḥīḥ Muslim; the Ḥanafīs hold it valid, citing Ibn ʿAbbās's report about Maymūna", "The Ḥanafīs hold it invalid; the majority hold it valid but disliked", "All four schools hold it valid without dislike", "All four schools hold it valid only if the bride is not in iḥrām"], "The hadith of ʿUthmān states that the muḥrim neither marries nor is given in marriage, so the Mālikīs, Shāfiʿīs and Ḥanbalīs void such a contract. The Ḥanafīs rely on Ibn ʿAbbās's report that the Prophet ﷺ married Maymūna while in iḥrām, which others answer with Maymūna's own report that he married her out of iḥrām."],
    de: ["Welche Aussage beschreibt den Meinungsunterschied über einen Ehevertrag, den eine Person im Iḥrām schließt, richtig?", ["Die Mehrheit hält ihn für ungültig, gestützt auf den Hadith von ʿUṯmān in Ṣaḥīḥ Muslim; die Ḥanafiten für gültig, gestützt auf den Bericht von Ibn ʿAbbās über Maimūna", "Die Ḥanafiten halten ihn für ungültig; die Mehrheit für gültig, aber verpönt", "Alle vier Schulen halten ihn ohne Bedenken für gültig", "Alle vier Schulen halten ihn nur für gültig, wenn die Braut nicht im Iḥrām ist"], "Der Hadith von ʿUṯmān besagt, dass der Muḥrim weder heiratet noch verheiratet wird; daher erklären Malikiten, Šāfiʿiten und Ḥanbaliten einen solchen Vertrag für nichtig. Die Ḥanafiten stützen sich auf den Bericht von Ibn ʿAbbās, der Prophet ﷺ habe Maimūna im Iḥrām geheiratet, dem die anderen Maimūnas eigenen Bericht entgegenhalten, er habe sie außerhalb des Iḥrām geheiratet."],
    ar: ["أيّ العبارات تصف الخلاف في عقد نكاح المحرم وصفًا صحيحًا؟", ["الجمهور: باطل لحديث عثمان في صحيح مسلم، والحنفية: صحيح لحديث ابن عباس في زواج ميمونة", "الحنفية: باطل، والجمهور: صحيح مع الكراهة", "الأربعة: صحيح بلا كراهة", "الأربعة: صحيح إذا لم تكن الزوجة محرمة"], "في حديث عثمان: لا يَنكح المحرم ولا يُنكح، فأبطله المالكية والشافعية والحنابلة، وصحّحه الحنفية لحديث ابن عباس أن النبي ﷺ تزوج ميمونة وهو محرم، وأجاب الجمهور بحديث ميمونة نفسها أنه تزوجها وهو حلال."] },

  { id: "fqz-092", s: "fiqh", g: 4, d: 4, t: ["talbiya", "school-differences"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ḥajj, on ending the talbiya; Khalīl, al-Mukhtaṣar, Bāb al-Ḥajj", tr: ["jumhur", "maliki", "comparative"],
    en: ["According to the Ḥanafīs, Shāfiʿīs and Ḥanbalīs, when does the pilgrim on ḥajj stop reciting the talbiya?", ["When he begins stoning Jamrat al-ʿAqaba on the Day of Sacrifice", "When he reaches the boundary of the Ḥaram", "When he arrives at ʿArafa on the morning of the 9th", "When he finishes ṭawāf al-ifāḍa"], "They follow the report of al-Faḍl ibn ʿAbbās that the Prophet ﷺ continued the talbiya until he stoned Jamrat al-ʿAqaba. The Mālikī school ends it earlier, when the pilgrim sets out for the place of prayer at ʿArafa after the sun passes the meridian; the talbiya of ʿumra ends on reaching the Ḥaram or starting ṭawāf, depending on the school."],
    de: ["Wann beendet der Ḥaǧǧ-Pilger nach Ḥanafiten, Šāfiʿiten und Ḥanbaliten das Rezitieren der Talbiya?", ["Wenn er am Opfertag mit dem Bewerfen der Ǧamrat al-ʿAqaba beginnt", "Wenn er die Grenze des Ḥaram erreicht", "Wenn er am Morgen des 9. in ʿArafa ankommt", "Wenn er den Ṭawāf al-Ifāḍa beendet"], "Sie folgen dem Bericht von al-Faḍl ibn ʿAbbās, dass der Prophet ﷺ die Talbiya fortsetzte, bis er die Ǧamrat al-ʿAqaba bewarf. Die malikitische Schule beendet sie früher, wenn der Pilger nach dem Mittagsscheitel zum Gebetsplatz in ʿArafa aufbricht; die Talbiya der ʿUmra endet je nach Schule beim Erreichen des Ḥaram oder mit Beginn des Ṭawāf."],
    ar: ["متى يقطع الحاج التلبية عند الحنفية والشافعية والحنابلة؟", ["مع ابتداء رمي جمرة العقبة يوم النحر", "عند بلوغ حدود الحرم", "عند الوصول إلى عرفة صباح التاسع", "بعد الفراغ من طواف الإفاضة"], "أخذوا بحديث الفضل بن عباس أن النبي ﷺ لم يزل يلبّي حتى رمى جمرة العقبة، وقطعها المالكية قبل ذلك عند الرواح إلى مصلّى عرفة بعد الزوال، أما المعتمر فيقطعها بدخول الحرم أو بالشروع في الطواف على خلاف بين المذاهب."] },

  { id: "fqz-093", s: "fiqh", g: 4, d: 5, t: ["hajj-pillars", "school-differences"], src: "al-Nawawī, Minhāj al-Ṭālibīn, Bāb Arkān al-Ḥajj wa-l-ʿUmra", tr: ["shafii", "comparative"],
    en: ["Al-Nawawī's Minhāj lists five pillars of ḥajj. Which one appears there that the Mālikīs and Ḥanbalīs do not count as a pillar?", ["Shaving or shortening the hair, on the view that it is a rite", "The farewell ṭawāf", "Stoning Jamrat al-ʿAqaba", "Staying overnight at Muzdalifa"], "The Minhāj names iḥrām, the standing, ṭawāf, saʿy and shaving, the last on the view that shaving is a rite (nusuk) and not merely a permission. These pillars cannot be replaced by a sacrifice. The Mālikīs and Ḥanbalīs count shaving among the wājibāt, and stoning and staying at Muzdalifa are wājibāt in all of these schools."],
    de: ["Al-Nawawīs Minhāǧ nennt fünf Säulen des Ḥaǧǧ. Welche erscheint dort, die Malikiten und Ḥanbaliten nicht als Säule zählen?", ["Das Rasieren oder Kürzen der Haare, nach der Ansicht, dass es ein Ritus ist", "Der Abschieds-Ṭawāf", "Das Bewerfen der Ǧamrat al-ʿAqaba", "Die Übernachtung in Muzdalifa"], "Der Minhāǧ nennt Iḥrām, das Stehen, Ṭawāf, Saʿy und das Rasieren, Letzteres nach der Ansicht, dass es ein Ritus (Nusuk) und nicht bloß eine Erlaubnis ist. Diese Säulen können nicht durch ein Opfer ersetzt werden. Malikiten und Ḥanbaliten zählen das Rasieren zu den Wāǧibāt, und das Steinigen sowie das Verweilen in Muzdalifa sind in all diesen Schulen Wāǧibāt."],
    ar: ["عدّ النووي في المنهاج أركان الحج خمسة، فأيّها لا يعدّه المالكية والحنابلة ركنًا؟", ["الحلق أو التقصير إذا جُعل نسكًا", "طواف الوداع", "رمي جمرة العقبة", "المبيت بمزدلفة"], "في المنهاج: أركان الحج خمسة: الإحرام والوقوف والطواف والسعي والحلق إذا جعلناه نسكًا، ولا تُجبر بدم، والحلق عند المالكية والحنابلة من الواجبات، والرمي والمبيت بمزدلفة واجبان في هذه المذاهب."] },

  { id: "fqz-094", s: "fiqh", g: 4, d: 4, t: ["hajj-months", "ihram", "school-differences"], src: "al-Nawawī, Minhāj al-Ṭālibīn, Bāb al-Mawāqīt; Ibn Qudāma, al-Mughnī", tr: ["shafii", "comparative"],
    en: ["Someone enters iḥrām for ḥajj in Ramaḍān, before the months of ḥajj. What is the position of the Shāfiʿī school?", ["The iḥrām does not count for ḥajj but turns into an iḥrām for ʿumra", "The iḥrām for ḥajj is valid but disliked", "The iḥrām is void and he leaves it without any rite", "The iḥrām is valid and he must perform qirān"], "Al-Nawawī states that iḥrām for ḥajj outside its time is not valid as ḥajj but takes effect as ʿumra, on the sound view, because the time of ḥajj is like the time of prayer. The Ḥanafīs, Mālikīs and Ḥanbalīs hold that it is valid for ḥajj though disliked."],
    de: ["Jemand tritt im Ramaḍān, vor den Ḥaǧǧ-Monaten, den Iḥrām für den Ḥaǧǧ an. Was ist die Position der šāfiʿitischen Schule?", ["Der Iḥrām zählt nicht für den Ḥaǧǧ, sondern wird zu einem Iḥrām für die ʿUmra", "Der Iḥrām für den Ḥaǧǧ ist gültig, aber verpönt", "Der Iḥrām ist nichtig und er verlässt ihn ohne Ritus", "Der Iḥrām ist gültig und er muss Qirān verrichten"], "An-Nawawī stellt fest, dass der Iḥrām für den Ḥaǧǧ außerhalb seiner Zeit nicht als Ḥaǧǧ gilt, sondern nach der richtigen Ansicht als ʿUmra wirksam wird, da die Zeit des Ḥaǧǧ der Gebetszeit gleicht. Ḥanafiten, Malikiten und Ḥanbaliten halten ihn für den Ḥaǧǧ für gültig, wenn auch verpönt."],
    ar: ["أحرم شخص بالحج في رمضان قبل أشهر الحج، فما قول الشافعية؟", ["لا ينعقد حجًّا وينعقد عمرة", "ينعقد حجًّا مع الكراهة", "يبطل الإحرام ويتحلل بلا نسك", "ينعقد ويلزمه القران"], "قال النووي: لو أحرم به في غير وقته انعقد عمرة على الصحيح، لأن وقت الحج كوقت الصلاة، وذهب الحنفية والمالكية والحنابلة إلى انعقاده حجًّا مع الكراهة."] },
];
